  f:"含<b>胞橋小體</b>（抗拉扯，心臟一直收縮也不會扯開）和<b>間隙接合</b>（電訊號直接傳到下一個細胞），讓整個心臟像一個單位同步收縮。",
  n:"intercalated＝「插在中間的」，指插在兩個細胞之間的盤狀構造。",
