  f:"細胞膜上密密麻麻的微小指狀突起，在顯微鏡下像刷子，稱為<b>刷狀緣</b> brush border，大幅增加吸收面積；膜上還有消化雙醣與胜肽的酵素。",
  n:"micro-（微小）＋ villi（絨毛）。小腸還有更大的「絨毛」villi，微絨毛是長在細胞上的更小一級。",
