  f:"一層單層鱗狀上皮，讓物質在血液與組織間交換；還會分泌一氧化氮（NO）等物質調節血管擴張與凝血。",
  n:"endo-（內）＋ -thelium（上皮）＝「襯在內面的上皮」。",
