 "動器":"eff","拮抗動器":"antag","拮抗":"antag","內在調節":"intr","自我調節":"intr","外在調節":"extr","激素":"horm",
 "神經傳遞物質":"nt","標的細胞":"target","受體":"receptor","基本組織":"tissue","主要組織":"tissue","上皮":"epi","上皮組織":"epi",
 "結締組織":"ct","細胞外基質":"ecm","基質":"ecm","基底物質":"gs","擴散":"diff","緊密連接":"tj","黏附連接":"aj","胞橋小體":"desmo",
 "間隙接合":"gap","細胞旁運輸":"para_t","穿細胞運輸":"trans_t","外分泌腺":"exo","內分泌腺":"endoG","假說":"hyp","對照組":"ctrl",
 "雙盲":"db","同儕審查":"peer","病理生理學":"patho","機制":"mech","理論":"theory","鱗狀":"shape","立方":"shape","柱狀":"shape",
 "單層":"layer","複層":"layer","偽複層":"pseudo","移行上皮":"trans_e","細胞內液":"icf","細胞外液":"ecf","組織間液":"isf",
