Object.assign(GL,{
 pmem:{t:"細胞膜（質膜）plasma membrane",d:"包住細胞的一層膜，由磷脂雙層、膽固醇、蛋白質與醣類組成，控制物質進出。",c:"3.1；第 6 章"},
 fmm:{t:"流體鑲嵌模型 fluid-mosaic model",d:"細胞膜的結構模型：<b>流體</b>＝磷脂分子可在膜中流動；<b>鑲嵌</b>＝蛋白質像馬賽克磁磚一樣嵌在膜裡。",e:"像一片浮著許多小船（蛋白質）的油膜。",c:"3.1"},
 semi:{t:"選擇性通透（半透性）selectively permeable",d:"膜只讓某些物質通過、擋住其他物質。",e:"像有門禁的大樓：有卡（通道、載體）的才能進。",c:"3.1；第 6 章"},
 integral:{t:"嵌入型蛋白、周邊蛋白 integral / peripheral proteins",d:"<b>嵌入型</b>：埋在膜中，許多貫穿整層膜（通道、載體、受體）。<b>周邊蛋白</b>：只附著在膜的表面。",c:"3.1"},
 glyx:{t:"醣萼 glycocalyx",d:"細胞膜外側醣蛋白與醣脂上的醣鏈形成的一層「糖衣」，用來讓細胞互相辨認。",e:"ABO 血型就是紅血球表面醣鏈的差異。",n:"glyco-（糖）＋ calyx（杯、外殼）。",c:"3.1；第 13、15 章"},
 phago:{t:"吞噬作用 phagocytosis",d:"細胞伸出偽足把<b>大顆粒</b>（細菌、碎片）整個包進來，再用溶體消化。",e:"嗜中性球、巨噬細胞吞細菌。",n:"phago-（吃）＋ cyte（細胞）。",c:"3.1；第 15 章"},
 pseudopod:{t:"偽足 pseudopod",d:"細胞膜與細胞質伸出的臨時突起，用來移動或包住東西。",n:"pseudo-（假）＋ pod（足）。",c:"3.1"},
 endocyt:{t:"胞吞作用 endocytosis",d:"細胞膜向內凹，把細胞外的物質包成膜泡帶進細胞。包括胞飲（喝液體）與受體媒介胞吞。",n:"endo-（內）＋ cyto（細胞）。",c:"3.1"},
 pino:{t:"胞飲作用 pinocytosis",d:"細胞非專一地把一小口細胞外液連同溶質包進來。",n:"pino-＝喝。",c:"3.1"},
 rme:{t:"受體媒介胞吞作用 receptor-mediated endocytosis",d:"物質先和細胞膜上的<b>專一受體</b>結合，再被包進細胞，專一又有效率。",e:"LDL 膽固醇、運鐵蛋白攜帶的鐵進入細胞。",c:"3.1；第 13 章"},
 exocyt:{t:"胞吐作用 exocytosis",d:"細胞內的分泌囊泡和細胞膜融合，把內容物倒到細胞外。",e:"釋放胰島素、神經傳遞物質、消化酶。",c:"3.1、3.4；第 7、11 章"},
 cilia:{t:"纖毛 cilia",d:"細胞表面許多短短的毛狀突起，內有 9＋2 排列的微管，會協調擺動，推動細胞表面的物質。",e:"呼吸道纖毛把痰往上推；輸卵管纖毛把卵子推向子宮。",c:"3.1；第 16、20 章"},
 flag:{t:"鞭毛 flagellum",d:"單一條長的運動構造，構造和纖毛相同（9＋2 微管），推動細胞前進。人類只有精子有。",c:"3.1；第 20 章"},
 cytoplasm:{t:"細胞質 cytoplasm",d:"細胞膜以內、細胞核以外的部分：胞液＋胞器＋內含物。",c:"3.2"},
 cytosol:{t:"胞液（細胞質液）cytosol",d:"細胞質中膠狀的液體部分，糖解作用等許多反應在這裡進行。",c:"3.2；第 5 章"},
 organelle:{t:"胞器 organelles",d:"細胞內有特定構造與功能的小單位，像工廠裡的各部門。",c:"3.2"},
 cytosk:{t:"細胞骨架 cytoskeleton",d:"細胞內的蛋白纖維網：<b>微絲</b>（肌動蛋白）、<b>中間絲</b>、<b>微管</b>（微管蛋白），負責形狀、運輸軌道、分裂。",c:"3.2"},
 mtub:{t:"微管 microtubules",d:"由微管蛋白組成的中空管子，是胞器運輸的軌道、纖毛與鞭毛的骨架、分裂時的紡錘絲。",c:"3.2、3.5"},
 lyso:{t:"溶體 lysosome",d:"內含消化酵素、內部酸性的膜囊，是細胞的<b>消化與回收站</b>。",n:"lyso-（分解）＋ soma（體）。",c:"3.2"},
 autoph:{t:"自噬作用 autophagy",d:"細胞把自己老舊或受損的胞器包起來送到溶體分解，回收原料；飢餓時增加。",n:"auto-（自己）＋ phagy（吃）。2016 年大隅良典因研究自噬獲諾貝爾獎。",c:"3.2"},
 apopt:{t:"細胞凋亡 apoptosis",d:"<b>計畫性</b>的細胞死亡：細胞有秩序地縮小、分解，被吞噬細胞清除，<b>不會引起發炎</b>。",e:"胚胎手指間的蹼消失；清除被病毒感染或 DNA 受損的細胞。",n:"希臘文「葉子凋落」。對比：壞死 necrosis 是受傷後腫脹破裂，會引起發炎。",c:"3.2、3.5"},
 perox:{t:"過氧化體 peroxisome",d:"含氧化酵素的小膜囊，氧化毒物與極長鏈脂肪酸時產生過氧化氫，再用過氧化氫酶分解掉。肝、腎特別多。",c:"3.2"},
 catalase:{t:"過氧化氫酶 catalase",d:"把有毒的過氧化氫（H₂O₂）分解成水和氧的酵素。",e:"雙氧水滴在傷口冒泡，就是組織中的過氧化氫酶在作用。",c:"3.2"},
 mito:{t:"粒線體 mitochondria",d:"細胞的<b>發電廠</b>：雙層膜，內膜摺成嵴；用氧把養分完全氧化，產生大部分 ATP。有自己的 DNA，母系遺傳。",n:"mito-（線）＋ chondrion（顆粒），在顯微鏡下像線或顆粒。",c:"3.2；第 5 章"},
 cristae:{t:"嵴 cristae",d:"粒線體內膜向內摺成的皺褶，增加面積，上面有電子傳遞鏈與 ATP 合成酶。",n:"拉丁文「雞冠」。",c:"3.2；第 5 章"},
 ribo:{t:"核糖體 ribosome",d:"由 rRNA 和蛋白質組成、合成蛋白質的小顆粒，分大小兩個次單元（人類 60S＋40S＝80S）。",c:"3.2、3.4"},
 er:{t:"內質網 endoplasmic reticulum",d:"由膜構成的管道與扁囊網路。<b>粗糙內質網</b>有核糖體，做分泌與膜蛋白；<b>平滑內質網</b>無核糖體，做脂質、解毒、儲存 Ca²⁺。",n:"endo-（內）＋ plasmic（細胞質）＋ reticulum（小網）。",c:"3.2、3.4"},
 rer:{t:"粗糙內質網 rough ER",d:"表面附著核糖體的內質網，合成要分泌出去或放在膜上的蛋白質。胰臟腺泡、漿細胞特別多。",c:"3.2、3.4"},
 ser:{t:"平滑內質網 smooth ER",d:"沒有核糖體的內質網：合成磷脂質與類固醇、肝臟解毒、儲存 Ca²⁺。",c:"3.2"},
 sr:{t:"肌漿網 sarcoplasmic reticulum",d:"肌肉細胞中特化的平滑內質網，儲存 Ca²⁺，神經刺激時釋放 Ca²⁺ 引起收縮。",c:"第 12 章"},
 golgi:{t:"高基氏體 Golgi complex",d:"一疊扁平膜囊，接收內質網送來的蛋白質，<b>修飾（加醣）、分類、包裝</b>成分泌囊泡或溶體。",e:"像郵局的包裹處理中心。",n:"1898 年義大利學者 Camillo Golgi 發現並以他命名。",c:"3.2、3.4"},
 nucleus2:{t:"細胞核 nucleus",d:"存放 DNA、控制細胞活動的胞器，由雙層核膜包住，有核孔讓 RNA 與蛋白質進出。",c:"3.3"},
 npore:{t:"核孔 nuclear pore",d:"核膜上的通道，讓 mRNA 出去、調控蛋白質進來。",c:"3.3"},
 nucleolus:{t:"核仁 nucleolus",d:"細胞核內深色的區域，製造 rRNA 並組裝核糖體次單元。",c:"3.3"},
 gene:{t:"基因 gene",d:"DNA 上一段能被轉錄成 RNA 的序列，通常帶有製造一種蛋白質的資訊。",c:"3.3"},
 genome:{t:"基因組 genome",d:"一個生物的全部 DNA。人類約 30 億鹼基對，約 2 萬多個編碼蛋白質的基因。",c:"3.3"},
 proteome:{t:"蛋白質體 proteome",d:"一個細胞或生物實際做出的所有蛋白質。因選擇性剪接與蛋白質修飾，種類比基因數多。",c:"3.3"},
 histone:{t:"組蛋白 histones",d:"帶正電的蛋白質，讓帶負電的 DNA 纏在上面，像線捲在線軸上。",c:"3.3"},
 chromatin:{t:"染色質 chromatin",d:"DNA 加上組蛋白等蛋白質的複合物。<b>真染色質</b>鬆散、基因可表現；<b>異染色質</b>緊密、基因關閉。",c:"3.3"},
 chromosome:{t:"染色體 chromosome",d:"細胞分裂時染色質高度濃縮成的棒狀構造。人類體細胞有 46 條（23 對）。",c:"3.3、3.5"},
 transcr:{t:"轉錄 transcription",d:"以 DNA 一股為模板，由 RNA 聚合酶合成 RNA 的過程，在細胞核進行。",e:"像把圖書館裡不能外借的原書（DNA）影印一頁（mRNA）帶出去。",c:"3.3"},
 rnapol:{t:"RNA 聚合酶 RNA polymerase",d:"結合在基因的啟動子上、依 DNA 模板合成 RNA 的酵素。",c:"3.3"},
 promoter:{t:"啟動子 promoter",d:"基因前方、讓 RNA 聚合酶結合並開始轉錄的 DNA 區域。",c:"3.3"},
 tf:{t:"轉錄因子 transcription factors",d:"結合在 DNA 特定序列上、決定某基因是否被轉錄的蛋白質，就像基因的開關。",e:"類固醇激素與甲狀腺素的受體就是轉錄因子。",c:"3.3；第 11 章"},
 exon:{t:"外顯子、內含子 exons / introns",d:"前驅 mRNA 中，<b>外顯子</b>會留在成熟 mRNA 並被轉譯；<b>內含子</b>夾在中間，會被剪掉。",m:"外顯子＝出去被表現；內含子＝留在裡面被剪掉。",c:"3.3"},
 splice:{t:"剪接 splicing",d:"把前驅 mRNA 的內含子剪掉、外顯子接起來。同一前驅 mRNA 保留不同外顯子組合，叫<b>選擇性剪接</b>，可做出不同蛋白質。",c:"3.3"},
 rnai:{t:"RNA 干擾 RNA interference",d:"microRNA 等小 RNA 和特定 mRNA 結合，使它被分解或無法轉譯，降低該基因的表現。",c:"3.3"},
 mirna:{t:"微小 RNA microRNA",d:"約 20 多個核苷酸、不編碼蛋白質的小 RNA，能抑制特定 mRNA 的轉譯。",c:"3.3、3.5"},
 transl:{t:"轉譯 translation",d:"核糖體依 mRNA 的密碼子，用 tRNA 帶來的胺基酸接成多胜肽的過程，在細胞質進行。",c:"3.4"},
 codon:{t:"密碼子 codon",d:"mRNA 上每 <b>3 個鹼基</b>為一組，對應一個胺基酸。AUG＝起始（甲硫胺酸）；UAA、UAG、UGA＝終止。",c:"3.4"},
 anticodon:{t:"反密碼子 anticodon",d:"tRNA 上 3 個鹼基，和 mRNA 的密碼子互補配對，確保帶來正確的胺基酸。",e:"密碼子 AUG ↔ 反密碼子 UAC。",c:"3.4"},
 trna:{t:"轉運 RNA tRNA",d:"一端接胺基酸、另一端有反密碼子的小 RNA，負責把胺基酸「翻譯」到正確位置。",c:"3.4"},
 polyribo:{t:"多核糖體 polyribosome",d:"一條 mRNA 同時被好幾個核糖體轉譯，提高生產量。",c:"3.4"},
 sigpep:{t:"訊號胜肽 signal peptide",d:"分泌性蛋白質開頭的一段胺基酸序列，像「地址標籤」，引導核糖體附到粗糙內質網上，之後被切掉。",c:"3.4"},
 cpep:{t:"C 胜肽 C-peptide",d:"胰島素原切成胰島素時被切掉的連接胜肽，與胰島素等量分泌。測血中 C 胜肽可估計病人自己的胰島素分泌能力。",c:"3.4；第 11、19 章"},
 ubiq:{t:"泛素 ubiquitin",d:"一種小蛋白質，接在要被分解的蛋白質上當「回收標籤」。",n:"ubiquitous＝無所不在，因為幾乎所有細胞都有。",c:"3.4"},
 proteasome:{t:"蛋白酶體 proteasome",d:"桶狀的蛋白酶複合體，把接上泛素的蛋白質切成小胜肽。",c:"3.4"},
 replic:{t:"DNA 複製 DNA replication",d:"細胞分裂前把 DNA 完整複製一份：解旋酶打開雙股，DNA 聚合酶依互補配對合成新股。",c:"3.5"},
 semicons:{t:"半保留複製 semiconservative replication",d:"複製後每個 DNA 分子含<b>一條舊股＋一條新股</b>。",c:"3.5"},
 dnapol:{t:"DNA 聚合酶 DNA polymerase",d:"以舊股為模板、依互補配對接上核苷酸合成新 DNA 股的酵素，有校對功能。",c:"3.5"},
 helicase:{t:"解旋酶 helicase",d:"打斷鹼基間的氫鍵、把 DNA 雙股拉開的酵素。",c:"3.5"},
 cellcycle:{t:"細胞週期 cell cycle",d:"細胞從一次分裂到下一次分裂的過程：<b>G1</b>（生長）→ <b>S</b>（複製 DNA）→ <b>G2</b>（準備）→ <b>M</b>（分裂）。不再分裂的叫 G0。",c:"3.5"},
 interphase:{t:"間期 interphase",d:"細胞週期中不在分裂的時期，包括 G1、S、G2，占週期大部分時間。",c:"3.5"},
 sister:{t:"姊妹染色分體 sister chromatids",d:"DNA 複製後，一條染色體變成的兩條完全相同的分體，由中節相連。",c:"3.5"},
 centromere:{t:"中節（著絲點）centromere",d:"連接兩條姊妹染色分體的部位，分裂時紡錘絲由此拉動染色體。",c:"3.5"},
 cyclin:{t:"週期素 cyclins",d:"濃度隨細胞週期起伏的蛋白質，和週期素依賴性激酶（CDK）結合，推動細胞進入下一期。",c:"3.5"},
 onco:{t:"致癌基因 oncogene",d:"促進細胞分裂的基因（原致癌基因）突變後過度活化，像「油門卡住」。",n:"onco-＝腫瘤。",c:"3.5"},
 tsg:{t:"抑癌基因 tumor suppressor gene",d:"抑制細胞分裂、像「煞車」的基因。失去功能時細胞容易失控分裂。最有名的是 <b>p53</b>。",c:"3.5"},
 p53:{t:"p53",d:"最重要的抑癌蛋白：偵測到 DNA 損傷時讓細胞週期停下修復，修不好就啟動凋亡。約一半的癌症有 p53 突變。",n:"分子量約 53 kDa 的蛋白質（p＝protein）。",c:"3.5"},
 necrosis:{t:"壞死 necrosis",d:"細胞因受傷（缺血、毒物、感染）腫脹破裂而死，內容物漏出會<b>引起發炎</b>；和凋亡不同。",c:"3.5"},
 telomere:{t:"端粒 telomere",d:"染色體末端的重複 DNA 序列，像鞋帶頭的塑膠套保護末端；每次分裂會變短一點。",e:"幹細胞、生殖細胞和多數癌細胞有端粒酶能把端粒補長。",n:"telo-（末端）＋ mere（部分）。",c:"3.5"},
 mitosis:{t:"有絲分裂 mitosis",d:"體細胞的分裂方式：前期、中期、後期、末期，產生<b>兩個相同的雙套</b>子細胞。",n:"mitos＝線，分裂時染色體像線一樣。",c:"3.5"},
 spindle:{t:"紡錘體 spindle",d:"分裂時由微管形成、從兩極伸向染色體的構造，把染色體拉向兩極。",c:"3.5"},
 centriole:{t:"中心粒 centrioles",d:"中心體中成對的圓柱狀微管構造，分裂時移向兩極、組織紡錘體；纖毛基部的基體也來自它。",c:"3.5"},
 cytokinesis:{t:"細胞質分裂 cytokinesis",d:"有絲分裂末期，細胞膜向內收縮，把細胞質分成兩個細胞。",c:"3.5"},
 meiosis:{t:"減數分裂 meiosis",d:"只在生殖細胞發生：DNA 複製一次、分裂兩次，產生<b>四個單套</b>（23 條）配子，遺傳組合各不相同。",n:"希臘文 meiosis＝減少。",c:"3.5；第 20 章"},
 diploid:{t:"雙套、單套 diploid / haploid",d:"<b>雙套（2n）</b>：染色體成對，人類 46 條，所有體細胞。<b>單套（n）</b>：每對只有一條，23 條，精子與卵子。",c:"3.5"},
 homolog:{t:"同源染色體 homologous chromosomes",d:"一對大小、形狀、基因位置都相同的染色體，一條來自父親、一條來自母親。",c:"3.5"},
 crossing:{t:"互換（交換）crossing-over",d:"第一次減數分裂時，配對的同源染色體在相同位置交換片段，使配子的遺傳組合更多樣。",c:"3.5"},
 epigen:{t:"表觀遺傳 epigenetics",d:"<b>不改變 DNA 序列</b>，而是用 DNA 甲基化、組蛋白修飾等改變基因的開關，而且可在細胞分裂時傳下去。",e:"懷孕期營養會影響胎兒的表觀遺傳標記。",n:"epi-＝在……之上，意思是「基因之上」的調控。",c:"3.3、3.5"},
 methyl:{t:"甲基化 methylation",d:"在 DNA 的胞嘧啶上加上甲基（–CH₃），通常使基因關閉。甲基來自葉酸、B12、膽鹼、甲硫胺酸代謝。",c:"3.3、3.5"},
 imprint:{t:"基因銘印 genomic imprinting",d:"某些基因只表現來自父親或母親的那一份，另一份被甲基化關閉。",c:"3.5"}
});
