Object.assign(GL,{
 catalyst:{t:"催化劑 catalyst",d:"能加快化學反應、本身反應前後不變的物質。身體的催化劑主要是酵素。",c:"4.1"},
 actE:{t:"活化能 activation energy",d:"反應開始前分子必須先具備的「能量門檻」。酵素把門檻降低，反應就容易發生。",e:"像翻過一座山：酵素在山腳開了隧道。",c:"4.1"},
 substrate:{t:"受質 substrate",d:"酵素作用的對象分子。",e:"乳糖是乳糖酶的受質。",c:"4.1"},
 asite:{t:"活性部位 active site",d:"酵素表面和受質結合、進行反應的凹槽，形狀與電荷剛好配合特定受質。",c:"4.1"},
 lockkey:{t:"鎖鑰模型 lock-and-key model",d:"受質像鑰匙、活性部位像鎖，形狀剛好吻合；用來解釋酵素的專一性。",c:"4.1"},
 induced:{t:"誘導契合 induced fit",d:"受質結合時，酵素的形狀會稍微改變，把受質包得更緊，比鎖鑰模型更接近實際情形。",e:"像手套被手撐開。",c:"4.1"},
 specif:{t:"專一性 specificity",d:"一種酵素只作用在一種或一類受質上；受體也只和特定分子結合。",c:"4.1"},
 kinase:{t:"激酶 kinase",d:"把磷酸基（通常來自 ATP）<b>接到</b>分子上的酵素。",m:"激酶＝加磷酸；磷酸酶＝拿掉磷酸。",c:"4.1、4.2；第 6 章"},
 phosphatase:{t:"磷酸酶 phosphatase",d:"把分子上的磷酸基<b>拿掉</b>的酵素。",c:"4.1、4.2"},
 dehydrog:{t:"脫氫酶 dehydrogenase",d:"把受質上的氫（電子）移走、交給 NAD⁺ 或 FAD 的酵素，催化氧化反應。",e:"乳酸脫氫酶（LDH）。",c:"4.1；第 5 章"},
 isozyme:{t:"同工酶 isoenzymes",d:"催化<b>相同反應</b>、但<b>結構不同</b>的酵素，常分布在不同器官；可用來判斷哪個器官受損。",e:"肌酸激酶 CK-MM（骨骼肌）、CK-MB（心肌）、CK-BB（腦）。",n:"iso-＝相同。",c:"4.1"},
 optimum:{t:"最適溫度、最適 pH optimum",d:"酵素活性最高的溫度與 pH。人體酵素最適溫度約 37°C；最適 pH 依酵素所在位置不同。",c:"4.2"},
 cofactor:{t:"輔因子 cofactor",d:"酵素需要的<b>金屬離子</b>，如 Mg²⁺、Zn²⁺、Fe、Cu、Mn、Se，幫助活性部位形成正確形狀或參與反應。",e:"這是許多礦物質之所以「必需」的原因。",c:"4.2"},
 coenzyme:{t:"輔酶 coenzyme",d:"酵素需要的<b>有機小分子</b>，大多由水溶性維生素（B 群）做成，負責搬運化學基團或電子。",e:"NAD⁺（菸鹼酸）、FAD（B2）、輔酶 A（泛酸）。",c:"4.2"},
 coa:{t:"輔酶 A coenzyme A",d:"由<b>泛酸</b>做成的輔酶，負責搬運乙醯基等，在克氏循環、脂肪酸代謝中很重要（乙醯輔酶 A）。",c:"4.2；第 5 章"},
 zymogen:{t:"酶原 zymogen",d:"不活化的酵素前驅物，要被切掉一段才會活化，保護製造它的細胞。",e:"胃蛋白酶原 → 胃蛋白酶；胰蛋白酶原 → 胰蛋白酶。",n:"zymo-（酵素）＋ -gen（產生）。",c:"4.2；第 18 章"},
 saturation:{t:"飽和 saturation",d:"所有酵素（或載體）都已被受質占滿，即使再增加受質，速率也不再上升。",e:"收費站全部車道都塞滿車，再多車也過不快。",c:"4.2；第 6、17 章"},
 massaction:{t:"質量作用定律 law of mass action",d:"可逆反應往哪邊進行，取決於兩邊物質的濃度：一邊多了，反應就被推向另一邊。",c:"4.2；第 16 章"},
 ca:{t:"碳酸酐酶 carbonic anhydrase",d:"催化 CO₂＋H₂O ⇌ H₂CO₃ 的酵素，在紅血球、腎小管、胃壁細胞中很重要；含鋅。",c:"4.2；第 16、17、18 章"},
 pathway:{t:"代謝路徑 metabolic pathway",d:"一連串由不同酵素催化的反應，前一個反應的產物是下一個反應的受質。",c:"4.2"},
 epinh:{t:"終產物抑制 end-product inhibition",d:"代謝路徑的終產物回頭抑制路徑前段的酵素，產品夠了就減少生產，是分子層次的負回饋。",c:"4.2"},
 allo:{t:"異位（變構）調節 allosteric regulation",d:"調節分子結合在酵素活性部位<b>以外</b>的位置，改變酵素形狀而增加或降低活性。",n:"allo-＝其他的；steric＝空間。",c:"4.2"},
 ratelim:{t:"速率限制酶 rate-limiting enzyme",d:"代謝路徑中最慢、決定整條路徑速度的那一步酵素，通常是被調控的對象。",e:"膽固醇合成的 HMG-CoA 還原酶（statin 藥物抑制它）。",c:"4.2"},
 iem:{t:"先天代謝異常 inborn errors of metabolism",d:"基因突變使代謝路徑中某個酵素缺乏，造成上游物質堆積、下游產物缺乏的遺傳疾病。",e:"苯酮尿症、半乳糖血症、楓糖尿症；新生兒篩檢可早期發現。",c:"4.2"},
 pku:{t:"苯酮尿症 phenylketonuria（PKU）",d:"缺乏苯丙胺酸羥化酶，苯丙胺酸無法轉成酪胺酸而堆積，損害腦部發育。治療：<b>低苯丙胺酸飲食</b>，酪胺酸要額外補充。",e:"含阿斯巴甜的飲料會標示「苯酮尿症患者不宜使用」。",c:"4.2；膳食療養"},
 bioen:{t:"生物能學 bioenergetics",d:"研究生物體內能量怎麼流動與轉換的學問。",c:"4.3"},
 exerg:{t:"釋能、吸能反應 exergonic / endergonic",d:"<b>釋能</b>：產物能量較低，反應放出能量（分解養分）。<b>吸能</b>：產物能量較高，需要輸入能量（合成、運動、主動運輸）。",m:"ex-＝出（放出）；end-＝入（吸入）。",c:"4.3"},
 catab:{t:"異化作用、同化作用 catabolism / anabolism",d:"<b>異化</b>：把大分子分解成小分子，放出能量。<b>同化</b>：用小分子合成大分子，消耗能量。兩者合稱代謝。",c:"4.3；第 5、19 章"},
 metab:{t:"代謝 metabolism",d:"身體內所有化學反應的總稱＝異化作用＋同化作用。",n:"希臘文 metabole＝改變。",c:"4.3"},
 coupled:{t:"偶聯反應 coupled reactions",d:"把吸能反應和一個釋能反應綁在一起，用後者放出的能量推動前者。ATP 是最常見的媒介。",c:"4.3"},
 atp:{t:"ATP 三磷酸腺苷 adenosine triphosphate",d:"細胞的<b>能量貨幣</b>：腺嘌呤＋核糖＋三個磷酸。ATP → ADP＋Pi 時放出能量，供肌肉收縮、主動運輸、合成反應使用；再由細胞呼吸充回。",e:"像可充電電池，或隨身的現金。",c:"4.3；第 5 章"},
 adp:{t:"ADP 二磷酸腺苷",d:"ATP 用掉一個磷酸後的形式，可再接上磷酸變回 ATP。",c:"4.3"},
 oxid:{t:"氧化 oxidation",d:"分子<b>失去電子</b>（生物反應中常以失去氫的方式）。",m:"OIL RIG：Oxidation Is Loss；中文「氧失還得」。",c:"4.3；第 5 章"},
 reduc:{t:"還原 reduction",d:"分子<b>得到電子</b>（或得到氫）。一定和氧化同時發生。",c:"4.3"},
 redox:{t:"氧化還原反應 redox reaction",d:"電子從一個分子轉移到另一個分子的反應：給出者被氧化，接受者被還原。",c:"4.3；第 5 章"},
 nad:{t:"NAD⁺／NADH",d:"由<b>菸鹼酸</b>做成的電子搬運者。NAD⁺（空車）接受電子變成 NADH（載滿），把電子送到電子傳遞鏈。",c:"4.3；第 5 章"},
 fad:{t:"FAD／FADH₂",d:"由<b>維生素 B2（核黃素）</b>做成的電子搬運者。FAD 接受電子變成 FADH₂。",c:"4.3；第 5 章"},
 nadph:{t:"NADPH",d:"另一種電子搬運者，主要供給<b>合成</b>反應（脂肪酸、膽固醇）與抗氧化系統使用；主要來自五碳醣磷酸路徑。",c:"4.3；第 5 章"},
 h2o2:{t:"過氧化氫 H₂O₂",d:"氧化反應產生的有毒副產物（雙氧水），由過氧化體的過氧化氫酶分解成水和氧。",c:"3.2"},
 etc:{t:"電子傳遞鏈 electron transport chain",d:"粒線體內膜上的一串蛋白質，把 NADH、FADH₂ 帶來的電子一站一站傳下去，最後交給氧形成水，途中放出的能量用來合成大量 ATP。",c:"第 5 章"}
});
