Object.assign(GL,{
 cellresp:{t:"細胞呼吸 cell respiration",d:"細胞把養分氧化、取出能量合成 ATP 的化學過程；和肺的呼吸不同，發生在每個細胞裡。",c:"5.1"},
 aerobic:{t:"有氧呼吸 aerobic respiration",d:"需要氧，養分被完全氧化成 CO₂ 和 H₂O，主要在粒線體進行，產生大量 ATP（每葡萄糖約 30–32）。",c:"5.2"},
 anaerobic:{t:"無氧代謝 anaerobic metabolism",d:"不用氧，只能走糖解並把丙酮酸變成乳酸，每葡萄糖只得 2 ATP，但速度快。",c:"5.1"},
 glycolysis:{t:"糖解作用 glycolysis",d:"在<b>細胞質</b>把 1 個葡萄糖切成 2 個丙酮酸，淨得 2 ATP 和 2 NADH，不需要氧。",n:"glyco-（糖）＋ lysis（分解）。",c:"5.1"},
 pyruvate:{t:"丙酮酸 pyruvic acid / pyruvate",d:"糖解的終產物（3 個碳）。有氧時進入粒線體變乙醯輔酶 A；缺氧時變成乳酸。",c:"5.1"},
 lactate:{t:"乳酸 lactic acid / lactate",d:"缺氧時丙酮酸接受 NADH 的電子形成的產物，讓 NAD⁺ 再生、糖解繼續。可送到肝臟做成葡萄糖，或被心肌當燃料。",c:"5.1；第 12 章"},
 hexokinase:{t:"己糖激酶 hexokinase",d:"糖解第一步的酵素，把葡萄糖加上磷酸成為葡萄糖-6-磷酸，把葡萄糖「關」在細胞內。肝臟用的是葡萄糖激酶。",c:"5.1"},
 pfk:{t:"磷酸果糖激酶 phosphofructokinase（PFK）",d:"糖解的<b>速率限制酶</b>；ATP 多時被抑制、AMP 多時被活化。",c:"5.1"},
 slp:{t:"受質層次磷酸化 substrate-level phosphorylation",d:"直接把受質分子上的磷酸轉給 ADP 形成 ATP，不需要氧（糖解、克氏循環中）。",c:"5.1"},
 g6p:{t:"葡萄糖-6-磷酸 glucose 6-phosphate",d:"葡萄糖進入細胞後被加上磷酸的形式，帶負電不能離開細胞；是糖解、肝醣合成、五碳醣路徑的分岔點。",c:"5.1"},
 g6pase:{t:"葡萄糖-6-磷酸酶 glucose-6-phosphatase",d:"把葡萄糖-6-磷酸的磷酸拿掉、變回可離開細胞的葡萄糖。<b>只在肝臟（與腎臟）</b>，所以只有肝能把葡萄糖釋放到血液。",c:"5.1；第 19 章"},
 glycogenesis:{t:"肝醣合成 glycogenesis",d:"把葡萄糖接成肝醣儲存（肝臟、肌肉），飯後由胰島素促進。",c:"5.1；第 19 章"},
 cori:{t:"柯氏循環 Cori cycle",d:"肌肉產生的乳酸經血液到肝臟，做成葡萄糖後再送回肌肉的循環。",n:"以 Carl 與 Gerty Cori 夫婦命名（1947 年諾貝爾獎）。",c:"5.1"},
 o2debt:{t:"氧債 oxygen debt",d:"運動後仍維持較高的耗氧量，用來補回磷酸肌酸、肌紅素的氧、處理乳酸、恢復體溫與心跳等；現稱運動後過耗氧量（EPOC）。",c:"5.1；第 12 章"},
 acoa:{t:"乙醯輔酶 A acetyl coenzyme A",d:"2 碳的乙醯基接在輔酶 A 上；醣、脂肪、部分胺基酸分解後都會變成它，是進入克氏循環的「共同入口」，也是合成脂肪酸、膽固醇、酮體的原料。",c:"5.2、5.3"},
 krebs:{t:"克氏循環 Krebs cycle（檸檬酸循環）",d:"在粒線體基質中，乙醯輔酶 A 和草醯乙酸結合成檸檬酸，再經一連串反應回到草醯乙酸；碳變成 CO₂，電子交給 NADH、FADH₂。",n:"以英國生化學家 Hans Krebs 命名（1953 年諾貝爾獎）；第一個產物是檸檬酸，所以也叫檸檬酸循環。",c:"5.2"},
 oaa:{t:"草醯乙酸 oxaloacetic acid",d:"克氏循環的起點與終點（4 碳），接上乙醯基形成檸檬酸；也是糖質新生的中間物。",c:"5.2"},
 citrate:{t:"檸檬酸 citric acid",d:"克氏循環的第一個產物（6 碳）。",c:"5.2"},
 cytochrome:{t:"細胞色素 cytochromes",d:"電子傳遞鏈中含鐵的蛋白質，負責接力傳遞電子；鐵缺乏會影響其功能。",n:"cyto-（細胞）＋ chrome（顏色），因含血基質而有顏色。",c:"5.2"},
 oxphos:{t:"氧化磷酸化 oxidative phosphorylation",d:"利用電子傳遞鏈（氧化）放出的能量，經 H⁺ 梯度推動 ATP 合成酶合成 ATP 的方式，產生細胞大部分的 ATP。",c:"5.2"},
 chemi:{t:"化學滲透理論 chemiosmotic theory",d:"電子傳遞把 H⁺ 打到膜間腔形成濃度梯度，H⁺ 經 ATP 合成酶流回時推動 ATP 合成。",e:"像水壩：抽水上去，水流下時推動水車發電。",n:"英國學者 Peter Mitchell 提出（1978 年諾貝爾獎）。",c:"5.2"},
 atpsyn:{t:"ATP 合成酶 ATP synthase",d:"粒線體內膜上的酵素，是 H⁺ 回流的通道；H⁺ 流過時帶動它旋轉，把 ADP＋Pi 合成 ATP。",c:"5.2"},
 ucp:{t:"解偶聯蛋白 uncoupling protein（UCP1）",d:"讓 H⁺ 不經 ATP 合成酶直接漏回基質，電子傳遞的能量變成熱而非 ATP；棕色脂肪特有。",c:"5.2、5.3"},
 brownfat:{t:"棕色脂肪 brown adipose tissue",d:"粒線體很多、含解偶聯蛋白的脂肪組織，專門<b>產熱</b>（非顫抖性產熱）。新生兒頸部與肩胛間較多。",c:"5.3；第 19 章"},
 lipogenesis:{t:"脂肪生成 lipogenesis",d:"由乙醯輔酶 A 合成脂肪酸、再組成三酸甘油酯，主要在肝臟與脂肪組織，飯後由胰島素促進。",c:"5.3；第 19 章"},
 lipolysis:{t:"脂肪分解 lipolysis",d:"脂肪組織的三酸甘油酯被水解成甘油與游離脂肪酸，釋入血液當燃料；空腹、運動、壓力時增加，胰島素抑制。",c:"5.3；第 19 章"},
 hsl:{t:"激素敏感性脂解酶 hormone-sensitive lipase",d:"脂肪細胞中分解三酸甘油酯的酵素；腎上腺素、升糖素使它活化，胰島素使它受抑制。",c:"5.3"},
 ffa:{t:"游離脂肪酸 free fatty acids",d:"脂肪分解後釋入血液的脂肪酸，由白蛋白攜帶，供肌肉、心臟、肝臟使用。",c:"5.3"},
 betaox:{t:"β 氧化 β-oxidation",d:"脂肪酸在粒線體中每次從一端切下 <b>2 個碳</b>成為乙醯輔酶 A，同時產生 NADH、FADH₂。",c:"5.3"},
 carnitine:{t:"肉鹼 carnitine",d:"把長鏈脂肪酸送進粒線體的載體分子；體內可由離胺酸、甲硫胺酸合成。",c:"5.3"},
 ketogenesis:{t:"生酮作用 ketogenesis",d:"肝臟在乙醯輔酶 A 過多時（禁食、低醣、糖尿病）把它轉成酮體。",c:"5.3；第 19 章"},
 aapool:{t:"胺基酸庫 amino acid pool",d:"體內隨時可用的游離胺基酸總和，來自飲食與蛋白質分解；身體沒有專門儲存胺基酸的組織。",c:"5.3"},
 nbal:{t:"氮平衡 nitrogen balance",d:"攝取的氮與排出的氮之比較。正氮平衡：生長、懷孕、恢復期；負氮平衡：飢餓、燒燙傷、重大傷病。",c:"5.3"},
 transam:{t:"轉胺作用 transamination",d:"把胺基酸的胺基轉給酮酸，形成新的胺基酸與酮酸；需維生素 B6。身體用它製造非必需胺基酸。",e:"ALT、AST 都是轉胺酶。",c:"5.3"},
 deamin:{t:"氧化去胺作用 oxidative deamination",d:"在肝臟把麩胺酸的胺基以氨（NH₃）的形式移除，剩下 α-酮戊二酸。",c:"5.3"},
 urea:{t:"尿素 urea",d:"肝臟以尿素循環把有毒的氨和 CO₂ 合成的含氮廢物，無毒、水溶性，由腎臟隨尿排出。",e:"血中尿素氮（BUN）是腎功能指標之一。",c:"5.3；第 17 章"},
 ureacycle:{t:"尿素循環 urea cycle",d:"肝臟中把氨轉成尿素的一連串反應（鳥胺酸循環），需消耗 ATP。肝衰竭時無法進行，血氨上升造成肝昏迷。",c:"5.3"},
 ammonia:{t:"氨 ammonia（NH₃）",d:"胺基酸去胺基後產生的含氮物質，對腦有毒，必須在肝臟轉成尿素。",c:"5.3"},
 gng2:{t:"生糖、生酮胺基酸 glucogenic / ketogenic",d:"<b>生糖</b>：碳骨架可變成丙酮酸或克氏循環中間物，能做成葡萄糖。<b>生酮</b>：碳骨架變成乙醯輔酶 A，只能產能或變成脂肪、酮體（白胺酸、離胺酸）。",c:"5.3"},
 glutamate:{t:"麩胺酸 glutamic acid",d:"轉胺作用把各種胺基酸的胺基集中到它身上，再在肝臟去胺；也是腦中主要的興奮性神經傳遞物質（第 7 章）。",c:"5.3"}
});
Object.assign(GL_ALIAS,{
 "細胞呼吸":"cellresp","有氧呼吸":"aerobic","無氧代謝":"anaerobic","糖解作用":"glycolysis","糖解":"glycolysis","丙酮酸":"pyruvate",
 "乳酸":"lactate","己糖激酶":"hexokinase","磷酸果糖激酶":"pfk","受質層次磷酸化":"slp","葡萄糖-6-磷酸":"g6p","葡萄糖-6-磷酸酶":"g6pase",
 "肝醣合成":"glycogenesis","柯氏循環":"cori","氧債":"o2debt","乙醯輔酶 A":"acoa","克氏循環":"krebs","檸檬酸循環":"krebs",
 "草醯乙酸":"oaa","檸檬酸":"citrate","細胞色素":"cytochrome","氧化磷酸化":"oxphos","化學滲透":"chemi","化學滲透理論":"chemi",
 "ATP 合成酶":"atpsyn","解偶聯蛋白":"ucp","棕色脂肪":"brownfat","脂肪生成":"lipogenesis","脂肪分解":"lipolysis",
 "激素敏感性脂解酶":"hsl","游離脂肪酸":"ffa","β 氧化":"betaox","肉鹼":"carnitine","生酮作用":"ketogenesis","胺基酸庫":"aapool",
 "氮平衡":"nbal","正氮平衡":"nbal","負氮平衡":"nbal","轉胺作用":"transam","轉胺":"transam","氧化去胺作用":"deamin","去胺":"deamin",
 "尿素":"urea","尿素循環":"ureacycle","氨":"ammonia","生糖胺基酸":"gng2","生酮胺基酸":"gng2","麩胺酸":"glutamate"
});

/* ---- end ch05 ---- */
/* ---- ch06 ---- */
Object.assign(GL,{
 integrin:{t:"整合素 integrins",d:"細胞膜上的蛋白質，一端抓住細胞外基質、一端連到細胞骨架，讓細胞附著並傳遞外界訊號。",c:"6.1"},
 passive:{t:"被動運輸 passive transport",d:"物質<b>順著濃度梯度</b>（高→低）移動，不需要細胞消耗能量：簡單擴散、滲透、促進性擴散。",e:"像球從山上滾下來。",c:"6.1"},
 active:{t:"主動運輸 active transport",d:"物質<b>逆著濃度梯度</b>（低→高）移動，需要能量：初級（直接用 ATP）、次級（借用 Na⁺ 梯度）。",e:"像把水抽到山上。",c:"6.3"},
 gradient:{t:"濃度梯度 concentration gradient",d:"兩處濃度的差異。物質會自然「順著梯度」從高往低移動。",c:"6.2"},
 bulk:{t:"大量運輸 bulk transport",d:"以膜泡一次搬運大量分子：胞吞（進）、胞吐（出）。",c:"6.3"},
 diffusion:{t:"擴散 diffusion",d:"分子因隨機運動，從<b>高濃度往低濃度</b>淨移動，直到平衡；不耗能。",e:"香水在房間裡慢慢散開。",c:"6.2"},
 simpdiff:{t:"簡單擴散 simple diffusion",d:"不需要膜蛋白，直接穿過磷脂雙層的擴散；適用於 O₂、CO₂、脂溶性分子。",c:"6.2"},
 ionch:{t:"離子通道 ion channel",d:"貫穿細胞膜、讓特定離子通過的蛋白質孔道。有的一直開（漏通道），有的依電壓或化學物質開關（閘控通道）。",c:"6.2；第 7 章"},
 aquaporin:{t:"水通道蛋白 aquaporins",d:"讓水快速通過細胞膜的通道蛋白。腎集尿管的水通道數量由 ADH 調控。",n:"aqua（水）＋ porin（孔）；2003 年 Peter Agre 因發現它獲諾貝爾化學獎。",c:"6.2；第 17 章"},
 osmosis:{t:"滲透 osmosis",d:"<b>水</b>穿過半透膜，從溶質少（水多）的一側，往溶質多（水少）的一側移動。",e:"醃菜時菜裡的水被鹽「拉」出來。",m:"水往鹹的地方流。",c:"6.2"},
 osmp:{t:"滲透壓 osmotic pressure",d:"阻止水滲透進入溶液所需的壓力；溶質顆粒越多，滲透壓越高、吸水力越強。",c:"6.2；第 14 章"},
 osmolality:{t:"滲透度 osmolality",d:"每公斤水中溶質<b>顆粒</b>的總莫耳數（Osm）。會解離的物質要乘以顆粒數。血漿約 300 mOsm。",c:"6.2；第 17 章"},
 tonicity:{t:"張力 tonicity",d:"溶液對細胞體積的影響。<b>等張</b>：不變；<b>低張</b>：細胞吸水膨脹；<b>高張</b>：細胞失水皺縮。只看細胞膜無法通過的溶質。",c:"6.2"},
 iso:{t:"等張、低張、高張 isotonic / hypotonic / hypertonic",d:"和細胞內相比：<b>等張</b>＝相同（0.9% NaCl、5% 葡萄糖）；<b>低張</b>＝溶質較少，水進細胞；<b>高張</b>＝溶質較多，水出細胞。",c:"6.2"},
 hemolysis:{t:"溶血 hemolysis",d:"紅血球破裂、血紅素流出。低張溶液、某些毒素、抗體或 G6PD 缺乏等都可能引起。",c:"6.2；第 13 章"},
 osmorec:{t:"滲透壓感受器 osmoreceptors",d:"下視丘中能偵測血漿滲透度的神經元；滲透度升高時引起口渴並促使 ADH 釋放。",c:"6.2；第 11、17 章"},
 osmdiur:{t:"滲透性利尿 osmotic diuresis",d:"腎小管內有大量無法回收的溶質（如糖尿病的葡萄糖），把水留在尿中，使尿量大增。",c:"6.2；第 17、19 章"},
 carrier:{t:"載體蛋白 carrier proteins",d:"和特定分子結合後改變形狀、把它帶過細胞膜的蛋白質。有專一性、競爭、飽和三特性。",c:"6.3"},
 tm:{t:"最大運輸量 transport maximum（Tm）",d:"所有載體都在工作時的最大運輸速率。",e:"腎小管葡萄糖的 Tm 被超過時，葡萄糖出現在尿中。",c:"6.3；第 17 章"},
 rthresh:{t:"腎糖閾 renal plasma threshold",d:"血糖超過約 180 mg/dL 時，腎小管無法回收全部濾出的葡萄糖，開始出現糖尿。",c:"6.3；第 17 章"},
 facdiff:{t:"促進性擴散 facilitated diffusion",d:"靠載體幫忙、但<b>順著</b>濃度梯度、不耗能的運輸。",e:"葡萄糖經 GLUT 進入細胞。",c:"6.3"},
 glut:{t:"葡萄糖轉運蛋白 GLUT",d:"以促進性擴散運送葡萄糖的載體家族。GLUT1 紅血球與血腦障壁、GLUT2 肝與 β 細胞、GLUT3 神經元、<b>GLUT4</b> 肌肉與脂肪（受胰島素調控）、GLUT5 果糖。",c:"6.3；第 11、18、19 章"},
 glut4:{t:"GLUT4",d:"骨骼肌、心肌、脂肪細胞的葡萄糖轉運蛋白，平常藏在細胞內的囊泡中；胰島素或運動使它插到細胞膜上。",c:"6.3；第 19 章"},
 ir:{t:"胰島素阻抗 insulin resistance",d:"肌肉、脂肪、肝臟對胰島素的反應變差，葡萄糖進不了細胞、肝臟持續輸出葡萄糖，胰臟只好分泌更多胰島素。是第 2 型糖尿病與代謝症候群的核心。",e:"內臟肥胖、缺乏運動、睡眠不足都會加重。",c:"6.3；第 19 章"},
 pump:{t:"幫浦 pump",d:"直接水解 ATP、把物質<b>逆梯度</b>運送的載體蛋白（初級主動運輸）。",c:"6.3"},
 nakpump:{t:"鈉鉀幫浦 Na⁺/K⁺ pump",d:"每用 1 個 ATP，把 <b>3 個 Na⁺ 送出、2 個 K⁺ 送入</b>，維持外鈉內鉀的梯度與膜電位，防止細胞腫脹。",n:"本身是一種 ATP 水解酶（Na⁺/K⁺-ATPase）。",c:"6.3、6.4；第 7 章"},
 capump:{t:"鈣幫浦 Ca²⁺ pump",d:"把 Ca²⁺ 打出細胞或打進內質網，使細胞質 Ca²⁺ 維持極低，Ca²⁺ 才能當作強烈的訊號。",c:"6.3；第 12 章"},
 primary:{t:"初級主動運輸 primary active transport",d:"運輸蛋白直接水解 ATP 取得能量，把物質逆梯度運送。",e:"鈉鉀幫浦、鈣幫浦、胃的 H⁺/K⁺ 幫浦。",c:"6.3"},
 secondary:{t:"次級主動運輸 secondary active transport",d:"利用 Na⁺ 順梯度流入的能量，帶著另一個物質逆梯度運送；間接依賴鈉鉀幫浦。",c:"6.3"},
 symport:{t:"同向運輸（共同運輸）symport / cotransport",d:"Na⁺ 和另一分子<b>同方向</b>一起進入細胞。",e:"小腸、腎小管的 Na⁺—葡萄糖同向運輸（SGLT）。",c:"6.3；第 17、18 章"},
 antiport:{t:"反向運輸 antiport / countertransport",d:"Na⁺ 進入、另一分子<b>反方向</b>出去。",e:"Na⁺/Ca²⁺ 交換器、Na⁺/H⁺ 交換器。",c:"6.3；第 17 章"},
 sglt:{t:"SGLT 鈉—葡萄糖同向運輸蛋白",d:"利用 Na⁺ 梯度把葡萄糖逆梯度帶進細胞的載體；SGLT1 在小腸、SGLT2 在腎近曲小管。",e:"SGLT2 抑制劑是一類降血糖藥，讓葡萄糖從尿排出。",c:"6.3；第 17、18 章"},
 ort:{t:"口服補液療法 oral rehydration therapy（ORT）",d:"用含<b>鈉與葡萄糖</b>的溶液治療腹瀉脫水：兩者經同向運輸一起被吸收，帶動水吸收。",c:"6.3；第 18 章"},
 absorb:{t:"吸收、再吸收 absorption / reabsorption",d:"<b>吸收</b>：從腸腔進入血液。<b>再吸收</b>：從腎小管濾液回到血液。",c:"6.3；第 17、18 章"},
 memp:{t:"膜電位 membrane potential",d:"細胞膜內外的電位差，以細胞內相對於細胞外表示（mV）；細胞內通常為負。",c:"6.4；第 7 章"},
 rmp:{t:"靜止膜電位 resting membrane potential（RMP）",d:"細胞未受刺激時的穩定膜電位，神經元約 <b>−70 mV</b>；主要由 K⁺ 梯度與 K⁺ 通透性決定。",c:"6.4；第 7 章"},
 eqp:{t:"平衡電位 equilibrium potential",d:"某離子的濃度推力和電荷拉力剛好相等、沒有淨移動時的膜電位。E<sub>K</sub> ≈ −90 mV、E<sub>Na</sub> ≈ +66 mV。",m:"誰的通道開，膜電位就靠近誰的平衡電位。",c:"6.4"},
 nernst:{t:"奈斯特方程式 Nernst equation",d:"由細胞內外濃度計算單一離子平衡電位的公式：E ＝ (61/z) log([外]/[內])（37°C）。",c:"6.4"},
 depol:{t:"去極化、過極化 depolarization / hyperpolarization",d:"<b>去極化</b>：膜電位變得比較不負（往 0 或正的方向）。<b>過極化</b>：膜電位變得更負。",c:"6.4；第 7 章"},
 hyperk:{t:"高血鉀、低血鉀 hyperkalemia / hypokalemia",d:"<b>高血鉀</b>（血鉀 > 5.0）：RMP 去極化，心律不整，嚴重時心臟停止。<b>低血鉀</b>（< 3.5）：過極化，肌肉無力、心電圖異常。",e:"腎衰竭易高血鉀，要限制高鉀食物；排鉀利尿劑、嘔吐、腹瀉易低血鉀。",c:"6.4；第 17 章"},
 electro:{t:"產電效應 electrogenic effect",d:"鈉鉀幫浦每次淨移出一個正電，直接使細胞內更負約 3 mV。",c:"6.4"},
 paracrine:{t:"旁泌 paracrine",d:"細胞分泌的化學訊號只作用在<b>附近</b>的細胞。",e:"生長因子、前列腺素、組織胺。",n:"para-＝旁邊。",c:"6.5"},
 autocrine:{t:"自泌 autocrine",d:"細胞分泌的訊號作用在<b>自己</b>身上。",n:"auto-＝自己。",c:"6.5"},
 endosig:{t:"內分泌 endocrine signaling",d:"激素經<b>血液</b>送到全身，只有具該激素受體的細胞會反應。",c:"6.5；第 11 章"},
 secmes:{t:"第二傳訊者 second messengers",d:"激素（第一傳訊者）結合膜受體後，在細胞內產生的小分子訊號，把命令傳到細胞內部並放大。",e:"cAMP、Ca²⁺、IP₃、DAG、cGMP。",c:"6.5；第 11 章"},
 camp:{t:"cAMP 環腺苷單磷酸",d:"由腺苷酸環化酶把 ATP 轉成的第二傳訊者，活化蛋白質激酶 A；被磷酸二酯酶分解。",c:"6.5；第 11 章"},
 adcyc:{t:"腺苷酸環化酶 adenylate cyclase",d:"細胞膜上的酵素，被 G 蛋白活化後把 ATP 轉成 cAMP。",c:"6.5"},
 pka:{t:"蛋白質激酶 protein kinase",d:"把磷酸接到其他蛋白質上、改變其活性的酵素。cAMP 活化的叫蛋白質激酶 A。",c:"6.5"},
 pde:{t:"磷酸二酯酶 phosphodiesterase",d:"分解 cAMP（或 cGMP）、結束訊號的酵素。咖啡因、茶鹼抑制它；威而鋼抑制分解 cGMP 的型。",c:"6.5"},
 gprot:{t:"G 蛋白 G-proteins",d:"受體與酵素或離子通道之間的中介，由 α、β、γ 三個次單元組成；活化時 α 的 GDP 換成 GTP 並分離，GTP 水解後關閉。",n:"能結合鳥苷酸（guanine nucleotide）而得名。",c:"6.5；第 9、11 章"},
 calmod:{t:"鈣調蛋白 calmodulin",d:"和 Ca²⁺ 結合後活化許多酵素的蛋白質，是 Ca²⁺ 作為第二傳訊者的主要媒介；平滑肌收縮也靠它。",c:"6.5；第 12 章"},
 ip3:{t:"IP₃ 與 DAG",d:"磷脂酶 C 分解細胞膜磷脂質產生的兩個第二傳訊者：IP₃ 使內質網釋放 Ca²⁺，DAG 活化蛋白質激酶 C。",c:"6.5；第 11 章"}
});
Object.assign(GL_ALIAS,{
 "整合素":"integrin","被動運輸":"passive","主動運輸":"active","濃度梯度":"gradient","大量運輸":"bulk","擴散":"diffusion","簡單擴散":"simpdiff",
 "離子通道":"ionch","通道":"ionch","水通道蛋白":"aquaporin","水通道":"aquaporin","滲透":"osmosis","滲透壓":"osmp","滲透度":"osmolality",
 "張力":"tonicity","等張":"iso","低張":"iso","高張":"iso","溶血":"hemolysis","滲透壓感受器":"osmorec","滲透性利尿":"osmdiur",
 "載體":"carrier","載體蛋白":"carrier","最大運輸量":"tm","腎糖閾":"rthresh","促進性擴散":"facdiff","GLUT":"glut","GLUT4":"glut4",
 "胰島素阻抗":"ir","幫浦":"pump","鈉鉀幫浦":"nakpump","鈣幫浦":"capump","初級主動運輸":"primary","次級主動運輸":"secondary",
 "同向運輸":"symport","共同運輸":"symport","反向運輸":"antiport","SGLT":"sglt","SGLT1":"sglt","SGLT2":"sglt","口服補液":"ort","口服補液鹽":"ort",
 "再吸收":"absorb","膜電位":"memp","靜止膜電位":"rmp","平衡電位":"eqp","奈斯特方程式":"nernst","去極化":"depol","過極化":"depol",
 "高血鉀":"hyperk","低血鉀":"hyperk","產電效應":"electro","旁泌":"paracrine","自泌":"autocrine","第二傳訊者":"secmes","cAMP":"camp",
 "腺苷酸環化酶":"adcyc","蛋白質激酶":"pka","磷酸二酯酶":"pde","G 蛋白":"gprot","鈣調蛋白":"calmod","IP₃":"ip3","DAG":"ip3"
});

