 "激素反應元":"hre","視網醇 X 受體":"rxr","RXR":"rxr","磷脂酶 C":"plc","酪胺酸激酶":"tyrk","前葉":"antpit","後葉":"antpit",
 "生長激素":"gh","GH":"gh","甲狀腺刺激素":"tsh","TSH":"tsh","促腎上腺皮質激素":"acth","ACTH":"acth","濾泡刺激素":"fsh","FSH":"fsh",
 "泌乳素":"prl","催乳素":"prl","PRL":"prl","促性腺激素":"gonadotropin","尿崩症":"di","門脈系統":"portal","釋放激素":"relhorm","抑制激素":"relhorm",
 "TRH":"trh","CRH":"trh","GnRH":"trh","GHRH":"trh","生長抑素":"somatostatin","IGF-1":"igf","類胰島素生長因子":"igf","體介素":"igf",
