 "甲狀腺功能低下":"hypothyroid","甲狀腺功能亢進":"hypothyroid","甲狀腺腫":"goiter","呆小症":"cretinism","葛瑞夫茲病":"graves","橋本氏甲狀腺炎":"hashimoto",
