Object.assign(GL,{
 co:{t:"心輸出量 cardiac output",d:"每分鐘一個心室打出的血量＝心率 × 心搏量；靜止約 5 L/分，劇烈運動可達 20–35 L/分。",c:"14.1"},
 hr:{t:"心率 heart rate",d:"每分鐘心跳次數；竇房結本身約 100，靜止時因迷走神經抑制約 70；交感與腎上腺素使其加快。",c:"14.1"},
 preload:{t:"前負荷、後負荷 preload / afterload",d:"<b>前負荷</b>：心舒期末容積，心肌被撐開的程度。<b>後負荷</b>：心室射血要克服的動脈壓與周邊阻力。",c:"14.1"},
 contractility:{t:"收縮力 contractility",d:"在相同心舒期末容積下心肌收縮的力量；交感神經與腎上腺素經 β₁、cAMP 使 Ca²⁺ 增加而增強（正變力作用）。",c:"14.1"},
 inotropic:{t:"變力作用、變時作用",d:"<b>變力</b>（inotropic）：改變收縮力。<b>變時</b>（chronotropic）：改變心率。交感兩者都是正向。",c:"14.1"},
 frankstarling:{t:"法蘭克—史達林定律 Frank-Starling law",d:"回流越多（EDV↑），心肌被拉長越多，收縮越強、心搏量越大；心臟的內在調節，使左右心室輸出相等。",e:"橡皮筋拉得越開，彈回越有力（在一定範圍內）。",c:"14.1"},
 tpr:{t:"總周邊阻力 total peripheral resistance",d:"全身血管對血流阻力的總和，主要由小動脈口徑決定；平均動脈壓 ≈ 心輸出量 × 總周邊阻力。",c:"14.1、14.3"},
 venreturn:{t:"靜脈回流 venous return",d:"每分鐘回到右心房的血量，決定心舒期末容積；靠靜脈收縮、骨骼肌幫浦、呼吸幫浦與血容積。",c:"14.1"},
 starlingf:{t:"史達林力 Starling forces",d:"決定微血管與組織間液體流動的力量：微血管靜水壓（推出）與血漿膠體滲透壓（拉回）。動脈端淨濾出、靜脈端淨吸回。",c:"14.2"},
 oncotic:{t:"膠體滲透壓 colloid osmotic pressure",d:"留在血管內的蛋白質（主要是白蛋白）產生的滲透壓，約 25 mmHg，把水拉回血管。",c:"14.2"},
 hydrostatic:{t:"靜水壓 hydrostatic pressure",d:"液體本身對管壁的壓力；在微血管就是血壓，把液體推出血管。",c:"14.2"},
 vasopressin:{t:"血管加壓素 vasopressin",d:"ADH 的另一個名字：高濃度時使血管收縮，故名。",c:"14.2、14.3"},
 renin:{t:"腎素 renin",d:"腎臟近腎絲球細胞在血壓或血量下降、交感興奮時分泌的酵素，把血管收縮素原切成血管收縮素 I。",c:"14.2；第 17 章"},
 jgcell:{t:"近腎絲球細胞 juxtaglomerular cells",d:"腎臟入球小動脈壁上的特化平滑肌細胞，感受血壓並分泌腎素。",c:"14.2；第 17 章"},
 angiotensin:{t:"血管收縮素 angiotensin",d:"血管收縮素原（肝）→ I（腎素）→ II（ACE）。<b>血管收縮素 II</b>：收縮小動脈、刺激醛固酮、口渴與 ADH。",c:"14.2"},
 ace:{t:"血管收縮素轉化酶 ACE",d:"主要在肺微血管內皮，把血管收縮素 I 轉成 II，也分解緩激肽；ACE 抑制劑（-pril）用來降血壓。",c:"14.2、14.7"},
 raas:{t:"腎素—血管收縮素—醛固酮系統 RAAS",d:"血壓↓ → 腎素 → 血管收縮素 II → 血管收縮＋醛固酮（保鈉保水）＋口渴與 ADH → 血壓回升。",c:"14.2"},
 arb:{t:"ACE 抑制劑、ARB",d:"降血壓藥：<b>ACE 抑制劑</b>（-pril）阻止血管收縮素 II 生成；<b>ARB</b>（-sartan）阻斷其受體。可能使血鉀上升。",c:"14.2、14.7"},
 natriuresis:{t:"利鈉作用 natriuresis",d:"腎臟排出鈉增加；ANP 與利尿劑都有此作用，水跟著鈉排出。",c:"14.2"},
 poiseuille:{t:"泊肅葉定律 Poiseuille's law",d:"流量與壓力差及半徑的四次方成正比，與管長及黏度成反比；半徑減半，流量剩 1/16。",c:"14.3"},
 viscosity:{t:"黏度 viscosity",d:"液體的濃稠程度；血液黏度主要由血比容決定，紅血球增多或脫水時增加。",c:"14.3"},
 vasocon:{t:"血管收縮、血管擴張 vasoconstriction / vasodilation",d:"血管平滑肌收縮使管徑變小、阻力增加；放鬆使管徑變大、阻力減少、血流增加。",c:"14.3"},
 autoreg:{t:"自動調節 autoregulation",d:"器官在血壓變動時自行維持穩定血流的能力，靠肌原性與代謝性機制；腦與腎最明顯。",c:"14.3、14.5"},
 myogenic:{t:"肌原性調節 myogenic regulation",d:"血管被血壓撐開時平滑肌反射性收縮、血壓降時放鬆，維持血流穩定。",c:"14.3"},
 metabolicreg:{t:"代謝性調節 metabolic regulation",d:"組織代謝旺盛時，O₂↓、CO₂、H⁺、K⁺、腺苷↑使局部小動脈擴張，血流增加。",c:"14.3"},
 hyperemia:{t:"充血 hyperemia",d:"局部血流增加：<b>主動充血</b>（運動時代謝增加）；<b>反應性充血</b>（血流被阻斷一段時間後恢復時血流大增）。",c:"14.3"},
 cgmp:{t:"cGMP（環鳥苷單磷酸）",d:"NO 活化鳥苷酸環化酶產生的第二傳訊者，使血管平滑肌放鬆；威而鋼抑制其分解。",c:"14.3；第 6 章"},
 coronary:{t:"冠狀動脈、冠狀循環 coronary circulation",d:"從主動脈根部發出供應心肌的動脈；心肌取氧率約 75%，需氧增加只能靠增加冠狀血流；左心室血流主要在心舒期。",c:"14.4；第 13 章"},
 avanast:{t:"動靜脈吻合 arteriovenous anastomoses",d:"皮膚（手、腳、耳、鼻）中讓血液繞過微血管直接從小動脈到小靜脈的通道，受交感控制，用於散熱或保熱。",c:"14.5"},
 bradykinin:{t:"緩激肽 bradykinin",d:"由血漿蛋白切出的胜肽，強力擴張血管、增加通透性並引起疼痛；被 ACE 分解（ACE 抑制劑的乾咳副作用與此有關）。",c:"14.5"},
 baro:{t:"壓力感受器 baroreceptors",d:"頸動脈竇（舌咽神經）與主動脈弓（迷走神經）壁上的伸張受器，偵測動脈血壓，傳到延腦。",c:"14.6"},
 baroreflex:{t:"壓力感受器反射 baroreceptor reflex",d:"血壓↓ → 感受器放電↓ → 交感↑、副交感↓ → 心率↑、血管收縮 → 血壓回升；反之亦然。短期負回饋。",c:"14.6"},
 carotidsinus:{t:"頸動脈竇、主動脈弓",d:"<b>頸動脈竇</b>：頸總動脈分叉處內頸動脈起端的膨大，有壓力感受器（舌咽神經）。<b>主動脈弓</b>：主動脈彎曲處（迷走神經）。注意化學感受器在頸動脈體與主動脈體（第 16 章）。",c:"14.6"},
 orthostatic:{t:"姿勢性（直立性）低血壓 orthostatic hypotension",d:"由躺或坐突然站起時血壓明顯下降而頭暈；壓力感受器反射不足、脫水、降壓藥、老年人常見。",c:"14.6"},
 valsalva:{t:"伐氏操作 Valsalva maneuver",d:"聲門關閉時用力呼氣 → 胸內壓↑ → 靜脈回流↓ → 血壓↓ → 心率反射性↑；放鬆後血壓回衝 → 心率↓。用力排便、舉重憋氣時發生。",c:"14.6（國考）"},
 bainbridge:{t:"班布里奇反射 Bainbridge reflex",d:"靜脈回流增加使心房被撐開時，心率反射性加快，把多出的血打出去。",c:"14.6"},
 korotkoff:{t:"柯氏音 sounds of Korotkoff",d:"以壓脈帶量血壓時，血液斷續通過被壓扁的動脈產生亂流的聲音：出現＝收縮壓，消失＝舒張壓。",c:"14.6"},
 sbp:{t:"收縮壓、舒張壓 systolic / diastolic pressure",d:"<b>收縮壓</b>：心室射血時動脈壓的最高值（約 120）。<b>舒張壓</b>：心舒期動脈壓的最低值（約 80）。",c:"14.6"},
 pulsepressure:{t:"脈壓 pulse pressure",d:"收縮壓－舒張壓（約 40 mmHg）；摸到的脈搏即由此產生；動脈硬化時變大。",c:"14.6"},
 map:{t:"平均動脈壓 mean arterial pressure",d:"≈ 舒張壓＋1/3 脈壓（120/80 約 93 mmHg），推動血液到各器官的平均壓力；≈ 心輸出量 × 總周邊阻力。",c:"14.6"},
 htn:{t:"高血壓 hypertension",d:"血壓持續偏高：簡報定義 ≥ 140/90 mmHg；台灣 2022 指引 ≥ 130/80 mmHg。九成以上為原發性；多無症狀卻損傷心、腦、腎與血管。",c:"14.7"},
 essentialhtn:{t:"原發性、續發性高血壓",d:"<b>原發性</b>（本態性，90–95%）：無單一原因，與鈉、肥胖、遺傳、腎臟、交感、RAAS 有關。<b>續發性</b>：有明確原因，如腎動脈狹窄、醛固酮過多、庫欣、嗜鉻細胞瘤。",c:"14.7"},
 dash:{t:"DASH 飲食",d:"Dietary Approaches to Stop Hypertension：多蔬果、全穀、低脂乳品、堅果豆類（富含鉀、鎂、鈣與纖維），少飽和脂肪、紅肉與甜食，配合減鈉。",c:"14.7"},
 diuretic:{t:"利尿劑 diuretics",d:"增加腎臟排鈉與排水的藥物，降低血容積與血壓；部分會使鉀流失（需注意低血鉀），保鉀型則可能使鉀升高。",c:"14.7；第 17 章"},
 betablocker:{t:"β 阻斷劑 β-blockers",d:"阻斷 β₁ 受體：減慢心率、降低收縮力與腎素分泌；用於高血壓、心絞痛、心衰竭、心律不整。",c:"14.7"},
 ccb:{t:"鈣通道阻斷劑 calcium channel blockers",d:"阻斷血管平滑肌（與心肌）的 L 型鈣通道，使血管放鬆擴張、降低血壓；葡萄柚汁會影響部分藥物的代謝。",c:"14.7"},
 lvh:{t:"左心室肥大 left ventricular hypertrophy",d:"長期高血壓使左心室後負荷增加，心肌增厚；初期代償，最後可能導致心衰竭與心律不整。",c:"14.7"},
 shock:{t:"循環性休克 circulatory shock",d:"組織灌流不足。類型：低血容積性、敗血性、過敏性、神經性、心因性。代償表現：心跳快、皮膚濕冷蒼白、尿少。",c:"14.7"},
 anaphylaxis:{t:"過敏性休克 anaphylactic shock",d:"嚴重過敏時大量組織胺使血管擴張、微血管漏液、支氣管收縮；需立即注射腎上腺素。",c:"14.7；第 15 章"},
 septic:{t:"敗血性休克 septic shock",d:"嚴重感染時細菌毒素引起大量 NO 與發炎物質，使血管廣泛擴張、通透性增加。",c:"14.7"},
 chf:{t:"鬱血性心衰竭 congestive heart failure",d:"心輸出量不足；腎臟保鈉保水使血量增加、靜脈壓升高：左心衰竭 → 肺水腫；右心衰竭 → 周邊水腫、肝腫大、頸靜脈怒張。",c:"14.7"},
 pulmedema:{t:"肺水腫 pulmonary edema",d:"肺微血管靜水壓升高（左心衰竭）或通透性增加，液體進入肺組織與肺泡，造成呼吸困難。",c:"14.7"},
 histamine:{t:"組織胺 histamine",d:"肥大細胞與嗜鹼性球釋放，使血管擴張、微血管通透性增加（紅腫）、支氣管收縮；胃中經 H₂ 受體促進胃酸。",c:"14.7；第 15、18 章"}
});
Object.assign(GL_ALIAS,{
 "心輸出量":"co","心率":"hr","前負荷":"preload","後負荷":"preload","收縮力":"contractility","正變力":"inotropic","變力作用":"inotropic","變時作用":"inotropic",
 "法蘭克—史達林定律":"frankstarling","法蘭克—史達林":"frankstarling","總周邊阻力":"tpr","周邊阻力":"tpr","靜脈回流":"venreturn","史達林力":"starlingf",
 "膠體滲透壓":"oncotic","靜水壓":"hydrostatic","ADH":"adh","血管加壓素":"vasopressin","腎素":"renin","近腎絲球細胞":"jgcell",
 "血管收縮素":"angiotensin","血管收縮素 II":"angiotensin","血管收縮素 I":"angiotensin","血管收縮素原":"angiotensin","ACE":"ace","血管收縮素轉化酶":"ace",
 "RAAS":"raas","腎素—血管收縮素—醛固酮系統":"raas","ACE 抑制劑":"arb","ARB":"arb","利鈉":"natriuresis","泊肅葉定律":"poiseuille","黏度":"viscosity",
 "血管收縮":"vasocon","血管擴張":"vasocon","自動調節":"autoreg","肌原性調節":"myogenic","代謝性調節":"metabolicreg","反應性充血":"hyperemia","cGMP":"cgmp",
 "冠狀動脈":"coronary","冠狀血流":"coronary","冠狀循環":"coronary","動靜脈吻合":"avanast","緩激肽":"bradykinin","壓力感受器":"baro","壓力感受器反射":"baroreflex",
 "頸動脈竇":"carotidsinus","主動脈弓":"carotidsinus","姿勢性低血壓":"orthostatic","直立性低血壓":"orthostatic","伐氏操作":"valsalva","班布里奇反射":"bainbridge",
 "柯氏音":"korotkoff","收縮壓":"sbp","舒張壓":"sbp","脈壓":"pulsepressure","平均動脈壓":"map","高血壓":"htn","原發性高血壓":"essentialhtn","續發性高血壓":"essentialhtn",
 "DASH":"dash","利尿劑":"diuretic","β 阻斷劑":"betablocker","鈣通道阻斷劑":"ccb","左心室肥大":"lvh","休克":"shock","循環性休克":"shock","過敏性休克":"anaphylaxis",
 "敗血性休克":"septic","心衰竭":"chf","鬱血性心衰竭":"chf","肺水腫":"pulmedema","組織胺":"histamine"
});

/* ---- end ch14 ---- */
/* ---- ch15 ---- */
Object.assign(GL,{
 innate:{t:"先天（非專一性）免疫 innate immunity",d:"生來就有的防禦：屏障、吞噬、NK 細胞、發炎、發燒、干擾素、補體；反應快、不專一、沒有記憶。",c:"15.1"},
 adaptive:{t:"後天（適應性、專一性）免疫 adaptive immunity",d:"接觸病原後學習而得：B 細胞（抗體，體液免疫）與 T 細胞（細胞媒介免疫）；專一且有記憶。",c:"15.1"},
 tlr:{t:"鐸樣受體 toll-like receptors（TLRs）",d:"免疫細胞上辨識病原體共有分子樣式（PAMPs）的受體，啟動先天免疫與發炎。",n:"Toll 原是果蠅的基因名（德文「好棒」）。",c:"15.1"},
 pamp:{t:"PAMPs、DAMPs",d:"<b>PAMPs</b>：病原體相關分子樣式，如細菌脂多醣、鞭毛、病毒 RNA。<b>DAMPs</b>：受損自身細胞釋放的傷害相關分子樣式。兩者都能啟動先天免疫。",c:"15.1"},
 chemokine:{t:"趨化因子、趨化作用 chemokines / chemotaxis",d:"<b>趨化因子</b>：吸引白血球的細胞激素。<b>趨化作用</b>：白血球順著化學物質濃度移動到感染處。",c:"15.1"},
 diapedesis:{t:"血球滲出（外滲）diapedesis / extravasation",d:"白血球在微血管後小靜脈壁上滾動、黏附，再從內皮細胞間擠出到組織的過程。",c:"15.1"},
 dendritic:{t:"樹突細胞 dendritic cells",d:"有許多分支突起的抗原呈現細胞，在皮膚與黏膜捕捉抗原，移到淋巴結呈現給 T 細胞，是連接先天與後天免疫的橋梁。",c:"15.1、15.3"},
 fixedphago:{t:"固著型吞噬細胞 fixed phagocytes",d:"固定在特定器官的吞噬細胞，如肝臟的庫佛氏細胞、肺泡巨噬細胞、腦的微膠細胞。",c:"15.1"},
 pyrogen:{t:"內生性致熱原 endogenous pyrogen",d:"白血球受細菌內毒素等刺激分泌的細胞激素（IL-1、IL-6、TNF-α），使下視丘產生 PGE₂、上調體溫設定點，並降低血漿鐵。",c:"15.1"},
 fever:{t:"發燒 fever",d:"體溫設定點被內生性致熱原上調；有助於抑制病原與加強免疫，NSAIDs 抑制前列腺素而退燒。",c:"15.1"},
 interferon:{t:"干擾素 interferons",d:"受病毒感染細胞分泌、使鄰近細胞進入抗病毒狀態的多肽：α、β 抑制病毒複製；γ（T、NK 細胞分泌）活化巨噬細胞。",c:"15.1"},
 antigen:{t:"抗原 antigen",d:"能刺激產生專一抗體或 T 細胞反應並與之結合的分子，多為外來蛋白質或多醣。",c:"15.1"},
 epitope:{t:"表位（抗原決定位）epitope",d:"抗原表面被抗體或 T 細胞受體實際辨認的小區域；一個大分子可有多個表位。",c:"15.1"},
 hapten:{t:"半抗原 hapten",d:"太小而不能單獨引起免疫反應的分子，與身體蛋白結合後才具抗原性，如盤尼西林、鎳。",c:"15.1、15.6"},
 immunoassay:{t:"免疫分析 immunoassay",d:"利用專一抗體偵測抗原的檢驗，如血型凝集、驗孕（hCG）、ELISA。",c:"15.1"},
 primarylymph:{t:"初級、次級淋巴器官",d:"<b>初級</b>：淋巴球成熟處——骨髓（B）、胸腺（T）。<b>次級</b>：淋巴球駐紮與遇抗原處——淋巴結、脾臟、扁桃腺、派亞氏斑。",c:"15.1"},
 peyer:{t:"派亞氏斑（培氏斑）Peyer's patches",d:"小腸（尤其迴腸）黏膜中的淋巴組織，監測腸道中的抗原，是腸道免疫的重要部分。",c:"15.1；第 18 章"},
 tcell:{t:"T 淋巴球 T lymphocyte",d:"在胸腺成熟；負責細胞媒介免疫：胞毒型殺受感染細胞、輔助型指揮、調節型抑制。",c:"15.1、15.3"},
 bcell:{t:"B 淋巴球 B lymphocyte",d:"在骨髓成熟；遇抗原後分化成漿細胞分泌抗體（體液免疫），並留下記憶 B 細胞。",c:"15.1、15.2"},
 cmi:{t:"細胞媒介免疫、體液免疫",d:"<b>細胞媒介免疫</b>：T 細胞直接攻擊（需近距離）。<b>體液免疫</b>：B 細胞分泌抗體到血液與淋巴（可遠距作用）。",c:"15.1"},
 plasmacell:{t:"漿細胞 plasma cell",d:"由 B 細胞分化而成的抗體工廠，粗糙內質網發達，每秒分泌數千個抗體，壽命短。",c:"15.2"},
 memorycell:{t:"記憶細胞 memory cells",d:"初次反應後留下的長壽 B 或 T 細胞，再次遇到同一抗原時迅速大量反應（次級反應）。",c:"15.2、15.4"},
 antibody:{t:"抗體（免疫球蛋白）antibody / immunoglobulin",d:"B 細胞（漿細胞）產生的 Y 字形蛋白質，專一結合抗原；作用：中和、凝集、調理、啟動補體。屬 γ 球蛋白。",c:"15.2"},
 igclass:{t:"五種抗體 IgG、IgA、IgM、IgD、IgE",d:"<b>IgG</b>：最多、過胎盤、次級反應主力。<b>IgA</b>：黏膜與乳汁。<b>IgM</b>：初級反應最早、五聚體。<b>IgD</b>：B 細胞表面受體。<b>IgE</b>：過敏與寄生蟲。",m:"GAMDE：G 最多過胎盤、A 在分泌物、M 最早最大。",c:"15.2"},
 colostrum:{t:"初乳 colostrum",d:"產後最初幾天的乳汁，色黃，富含分泌型 IgA、蛋白質與免疫細胞，給嬰兒被動免疫。",c:"15.2、15.4；第 20 章"},
 abstructure:{t:"抗體的構造",d:"兩條重鏈＋兩條輕鏈以雙硫鍵連成 Y 字形；手臂末端的可變區（Fab）結合抗原，尾巴的恆定區（Fc）決定類型並與吞噬細胞、補體結合。",c:"15.2"},
 opsonization:{t:"調理作用 opsonization",d:"抗體或補體（C3b）黏附在病原體表面，使吞噬細胞更容易辨認與吞噬。",n:"opson＝希臘文「調味料」，讓病原變得「好吃」。",c:"15.2"},
 complement:{t:"補體系統 complement system",d:"約 20 種血漿蛋白的連鎖活化系統；古典路徑由抗體啟動，替代路徑由病原表面直接啟動；結果：膜攻擊複合物溶菌、C3b 調理、C3a/C5a 發炎。",n:"補足（complement）抗體的作用。",c:"15.2"},
 mac:{t:"膜攻擊複合物 membrane attack complex",d:"補體 C5–C9 組成的孔洞，插入細菌細胞膜使水與離子湧入而溶解。",c:"15.2"},
 mastcell:{t:"肥大細胞 mast cells",d:"結締組織中充滿顆粒的細胞，去顆粒時釋放組織胺、肝素、白三烯素等，引起發炎與立即型過敏；表面可附著 IgE。",c:"15.2、15.6"},
 tnf:{t:"腫瘤壞死因子 TNF-α",d:"巨噬細胞等分泌的發炎性細胞激素，引起發燒、發炎，可殺死某些腫瘤細胞；過多與惡病質、胰島素阻抗有關。",c:"15.2、15.5"},
 inflammation:{t:"發炎 inflammation",d:"組織受傷或感染時的反應：血管擴張與通透性增加，出現紅、熱、腫、痛；吞噬細胞與補體清除病原與碎片。",c:"15.2"},
 ctl:{t:"胞毒型 T 細胞（殺手 T）cytotoxic T cell",d:"CD8⁺；辨認第一型 MHC 呈現的抗原，以穿孔素與顆粒酶殺死被病毒感染的細胞、癌細胞與移植細胞。",c:"15.3"},
 helpert:{t:"輔助型 T 細胞 helper T cell",d:"CD4⁺；辨認第二型 MHC 呈現的抗原，分泌細胞激素活化 B 細胞、胞毒型 T 與巨噬細胞；分 Th1、Th2、Th17。HIV 感染此細胞。",c:"15.3"},
 treg:{t:"調節型 T 細胞 regulatory T cell",d:"CD4⁺CD25⁺（FOXP3）；抑制免疫反應，維持對自身的耐受性，防止自體免疫與過度發炎。",c:"15.3、15.4"},
 perforin:{t:"穿孔素、顆粒酶 perforin / granzymes",d:"胞毒型 T 與 NK 細胞釋放：穿孔素在目標細胞膜上打洞，顆粒酶進入後引發細胞凋亡。",c:"15.3"},
 mhc:{t:"主要組織相容複合體 MHC（HLA）",d:"把抗原片段呈現給 T 細胞的「托盤」。<b>第一型</b>：所有有核細胞，給 CD8。<b>第二型</b>：抗原呈現細胞，給 CD4。每人不同，是移植排斥的原因。",c:"15.3"},
 apc:{t:"抗原呈現細胞 antigen-presenting cells",d:"能以第二型 MHC 呈現外來抗原給輔助型 T 細胞的細胞：巨噬細胞、樹突細胞、B 細胞。",c:"15.3"},
 interleukin:{t:"介白素 interleukins",d:"白血球之間溝通的細胞激素：IL-1（巨噬細胞，活化 T 細胞、致熱）、IL-2（使 T 細胞增生）、IL-4/5（Th2，促進 B 細胞與 IgE）等。",c:"15.3"},
 aids:{t:"愛滋病 AIDS",d:"人類免疫缺乏病毒（HIV）感染 CD4 輔助型 T 細胞造成的後天免疫缺乏症候群，易發生伺機性感染與癌症；以抗反轉錄病毒藥物控制。",c:"15.3"},
 fas:{t:"FAS 與 FAS 配體",d:"結合後觸發細胞凋亡的受體與配體；用來在感染後清除活化的 T 細胞，也讓免疫特權部位與某些腫瘤殺死攻擊的 T 細胞。",c:"15.3、15.5"},
 privileged:{t:"免疫特權部位 immunologically privileged sites",d:"免疫反應受抑制的部位，如眼睛前房、睪丸細精管；細胞表現 FAS 配體使進入的 T 細胞凋亡。",c:"15.3"},
 primaryresp:{t:"初級、次級免疫反應",d:"<b>初級</b>：首次接觸，5–10 天才有抗體（IgM 先），量少，會生病。<b>次級</b>：再次接觸，數小時內上升、數天達高峰、量多（IgG）、持久。",c:"15.4"},
 clonalsel:{t:"株落選擇理論 clonal selection theory",d:"每種淋巴球只辨認一種抗原；抗原「選中」相符的少數淋巴球，使其分裂成大量相同細胞（株落）——效應細胞與記憶細胞。",c:"15.4"},
 active:{t:"主動免疫、被動免疫",d:"<b>主動</b>：自己產生抗體與記憶（感染、疫苗），慢但持久。<b>被動</b>：得到現成抗體（胎盤、母乳、抗血清），立即但短暫、無記憶。",c:"15.4"},
 vaccine:{t:"疫苗 vaccine",d:"引起初級反應與記憶而不致病：不活化、減毒活、重組次單位、類毒素、mRNA 或病毒載體疫苗；常加佐劑並追加劑。",c:"15.4"},
 attenuated:{t:"減毒活疫苗、不活化疫苗",d:"<b>減毒活</b>：病原活著但毒性減弱（沙賓口服小兒麻痺、MMR、卡介苗）。<b>不活化</b>：病原已殺死（沙克小兒麻痺、流感）。",c:"15.4"},
 adjuvant:{t:"佐劑 adjuvant",d:"與疫苗一起給、增強免疫反應的物質，多藉模仿 PAMPs 活化先天免疫。",c:"15.4"},
 tolerance:{t:"免疫耐受性 immunological tolerance",d:"對自身抗原不反應。中央耐受：胸腺與骨髓中刪除自我反應淋巴球（株落刪除）；周邊耐受：株落無能、調節型 T 抑制。",c:"15.4"},
 antiserum:{t:"抗血清、免疫球蛋白製劑",d:"含現成抗體的製劑（抗蛇毒血清、破傷風、狂犬病、B 肝免疫球蛋白），提供立即的人工被動免疫。",c:"15.4"},
 mab:{t:"單株抗體 monoclonal antibody",d:"由同一個融合瘤（B 細胞＋骨髓瘤）株落產生、只針對單一表位的抗體；用於診斷與治療（藥名多 -mab）。",c:"15.4、15.5"},
 hybridoma:{t:"融合瘤 hybridoma",d:"產生抗體的 B 細胞與能無限分裂的骨髓瘤細胞融合而成，用來大量生產單株抗體。",c:"15.4"},
 tumor:{t:"良性、惡性腫瘤",d:"<b>良性</b>：生長慢、局限、有包膜。<b>惡性（癌）</b>：生長快、侵犯周圍並轉移。",c:"15.5"},
 metastasis:{t:"轉移 metastasis",d:"惡性腫瘤細胞經血液或淋巴擴散到遠處器官形成新腫瘤。",c:"15.5"},
 tumorag:{t:"腫瘤抗原、腫瘤標記",d:"腫瘤細胞表現的胚胎抗原（CEA、AFP）、突變蛋白、病毒抗原（HPV）或過度表現的蛋白；部分可作血液檢驗的腫瘤標記。",c:"15.5"},
 nk:{t:"自然殺手細胞 natural killer cells",d:"先天免疫的淋巴球，不需辨認專一抗原，殺死第一型 MHC 減少的腫瘤或病毒感染細胞（穿孔素、顆粒酶），並分泌 γ 干擾素。",c:"15.1、15.5"},
 surveillance:{t:"免疫監督 immunological surveillance",d:"免疫系統（胞毒型 T、NK 細胞）持續偵測並清除癌化細胞的功能；失敗時癌症發展。",c:"15.5"},
 checkpoint:{t:"免疫檢查點抑制劑 checkpoint inhibitors",d:"阻斷 PD-1、PD-L1 或 CTLA-4 的單株抗體，解除 T 細胞的煞車讓它攻擊癌細胞；可能引起自體免疫副作用。",c:"15.5"},
 cachexia:{t:"惡病質 cachexia",d:"癌症或慢性疾病時，發炎性細胞激素使食慾下降、肌肉與脂肪大量分解的消耗狀態，單靠增加熱量難以逆轉。",c:"15.5"},
 autoimmune:{t:"自體免疫疾病 autoimmune disease",d:"對自身抗原耐受失敗，自體反應 T 細胞與自體抗體攻擊自身組織；如第 1 型糖尿病、類風濕性關節炎、狼瘡、多發性硬化、乳糜瀉。",c:"15.6"},
 ra:{t:"類風濕性關節炎 rheumatoid arthritis",d:"自體免疫攻擊關節滑膜，產生類風濕因子（對抗自身 IgG 的抗體）與免疫複合體，造成關節發炎變形。",c:"15.6"},
 sle:{t:"全身性紅斑性狼瘡 SLE",d:"產生抗核抗體等自體抗體，形成免疫複合體沉積於皮膚、關節、腎臟等多器官；女性多。",c:"15.6"},
 ms:{t:"多發性硬化症 multiple sclerosis",d:"自體免疫攻擊中樞神經的髓鞘（寡突膠細胞），使神經傳導受損，症狀時好時壞。",c:"15.6；第 7 章"},
 pernicious:{t:"惡性貧血 pernicious anemia",d:"自體免疫破壞胃壁細胞或內在因子，維生素 B12 無法吸收造成的巨球性貧血；需注射 B12。",c:"15.6；第 13、18 章"},
 rheumaticfever:{t:"風濕熱、腎絲球腎炎",d:"A 群鏈球菌感染後，抗體與心臟瓣膜（風濕熱）或腎絲球（腎絲球腎炎）的相似抗原交叉反應而造成損傷。",c:"15.6"},
 celiac:{t:"乳糜瀉 celiac disease",d:"對小麥、大麥、黑麥中的麩質產生自體免疫反應，使小腸絨毛萎縮、吸收不良；治療為終身無麩質飲食。",c:"15.6；第 18 章"},
 immunecomplex:{t:"免疫複合體疾病 immune complex disease",d:"過多或持續的抗原—抗體複合物沉積在血管、腎絲球、關節，活化補體與發炎（如 B 肝相關血管炎、狼瘡腎炎）。",c:"15.6"},
 allergy:{t:"過敏 allergy（hypersensitivity）",d:"對無害過敏原的異常免疫反應：立即型（IgE、肥大細胞、數分鐘）與遲發型（T 細胞、24–72 小時）。",c:"15.6"},
 allergen:{t:"過敏原 allergen",d:"引起過敏的抗原，如花粉、塵蟎、蝦蟹、花生、牛奶蛋白、蛋、蜂毒、藥物。",c:"15.6"},
 immediatehs:{t:"立即型過敏 immediate hypersensitivity",d:"首次接觸產生 IgE 附在肥大細胞上；再次接觸時過敏原交聯 IgE，肥大細胞釋放組織胺、白三烯素，數分鐘內出現蕁麻疹、鼻炎、氣喘，嚴重時過敏性休克。",c:"15.6"},
 delayedhs:{t:"遲發型過敏 delayed hypersensitivity",d:"T 細胞媒介，接觸後 24–72 小時出現，如接觸性皮膚炎（毒漆藤、鎳）、結核菌素皮膚測驗；抗組織胺無效。",c:"15.6"},
 antihistamine:{t:"抗組織胺 antihistamines",d:"阻斷組織胺受體的藥物：H₁ 阻斷劑治療過敏性鼻炎、蕁麻疹；H₂ 阻斷劑減少胃酸（第 18 章）。",c:"15.6"},
 foodintol:{t:"食物過敏、食物不耐",d:"<b>食物過敏</b>：對食物蛋白的免疫反應（多為 IgE），少量即可能嚴重。<b>食物不耐</b>：非免疫性，如乳糖酶不足的乳糖不耐，與攝取量有關。",c:"15.6；第 18 章"}
});
Object.assign(GL_ALIAS,{
 "先天免疫":"innate","非專一性免疫":"innate","後天免疫":"adaptive","適應性免疫":"adaptive","專一性免疫":"adaptive","鐸樣受體":"tlr","TLR":"tlr","PAMPs":"pamp","DAMPs":"pamp",
 "趨化因子":"chemokine","趨化作用":"chemokine","血球滲出":"diapedesis","外滲":"diapedesis","樹突細胞":"dendritic","固著型吞噬細胞":"fixedphago","內生性致熱原":"pyrogen",
 "發燒":"fever","干擾素":"interferon","抗原":"antigen","表位":"epitope","抗原決定位":"epitope","半抗原":"hapten","免疫分析":"immunoassay",
 "初級淋巴器官":"primarylymph","次級淋巴器官":"primarylymph","派亞氏斑":"peyer","培氏斑":"peyer","T 淋巴球":"tcell","T 細胞":"tcell","B 淋巴球":"bcell","B 細胞":"bcell",
 "細胞媒介免疫":"cmi","體液免疫":"cmi","漿細胞":"plasmacell","記憶細胞":"memorycell","抗體":"antibody","免疫球蛋白":"antibody",
 "IgG":"igclass","IgA":"igclass","IgM":"igclass","IgD":"igclass","IgE":"igclass","初乳":"colostrum","可變區":"abstructure","恆定區":"abstructure",
 "調理作用":"opsonization","補體":"complement","補體系統":"complement","膜攻擊複合物":"mac","肥大細胞":"mastcell","腫瘤壞死因子":"tnf","TNF-α":"tnf","發炎":"inflammation",
 "胞毒型 T 細胞":"ctl","殺手 T":"ctl","胞毒型 T":"ctl","輔助型 T 細胞":"helpert","輔助型 T":"helpert","調節型 T 細胞":"treg","調節型 T":"treg","穿孔素":"perforin","顆粒酶":"perforin",
 "MHC":"mhc","主要組織相容複合體":"mhc","HLA":"mhc","抗原呈現細胞":"apc","介白素":"interleukin","愛滋病":"aids","HIV":"aids","AIDS":"aids","FAS":"fas","FAS 配體":"fas",
 "免疫特權部位":"privileged","初級反應":"primaryresp","次級反應":"primaryresp","株落選擇理論":"clonalsel","株落":"clonalsel","主動免疫":"active","被動免疫":"active",
 "疫苗":"vaccine","減毒活疫苗":"attenuated","不活化疫苗":"attenuated","佐劑":"adjuvant","免疫耐受性":"tolerance","株落刪除":"tolerance","株落無能":"tolerance",
 "抗蛇毒血清":"antiserum","單株抗體":"mab","融合瘤":"hybridoma","良性腫瘤":"tumor","惡性腫瘤":"tumor","腫瘤抗原":"tumorag","CEA":"tumorag","甲型胎兒蛋白":"tumorag",
 "自然殺手細胞":"nk","NK 細胞":"nk","免疫監督":"surveillance","免疫檢查點抑制劑":"checkpoint","惡病質":"cachexia","自體免疫":"autoimmune","自體免疫疾病":"autoimmune",
 "類風濕性關節炎":"ra","紅斑性狼瘡":"sle","狼瘡":"sle","多發性硬化":"ms","多發性硬化症":"ms","惡性貧血":"pernicious","風濕熱":"rheumaticfever","腎絲球腎炎":"rheumaticfever",
 "乳糜瀉":"celiac","免疫複合體":"immunecomplex","過敏":"allergy","過敏原":"allergen","立即型過敏":"immediatehs","遲發型過敏":"delayedhs","抗組織胺":"antihistamine",
 "食物過敏":"foodintol","食物不耐":"foodintol"
});

