/* ---- ch16 ---- */
Object.assign(GL,{
 ventilation:{t:"換氣 ventilation",d:"空氣進出肺的呼吸動作；與氣體交換（擴散）、細胞呼吸合稱呼吸。",c:"16.1"},
 alveoli:{t:"肺泡 alveoli",d:"約 3 億個小氣囊，總面積約 60–80 m²，壁極薄、外圍密布微血管，是氣體交換的地方。",c:"16.1"},
 alvcell:{t:"第一型、第二型肺泡細胞",d:"<b>第一型</b>：極扁平，占表面 95%，與微血管組成約 0.3 µm 的呼吸膜。<b>第二型</b>：分泌表面活性劑。",c:"16.1"},
 condzone:{t:"傳導區、呼吸區",d:"<b>傳導區</b>：鼻到終末細支氣管，送氣、加溫、加濕、過濾，不交換氣體。<b>呼吸區</b>：呼吸性細支氣管、肺泡管、肺泡，進行交換。",c:"16.1"},
 mucocil:{t:"黏液纖毛電扶梯 mucociliary escalator",d:"呼吸道杯狀細胞分泌黏液黏住微粒，纖毛把黏液往咽部推送；抽菸破壞纖毛。",c:"16.1"},
 pleura:{t:"胸膜、胸膜腔 pleura",d:"臟層胸膜覆蓋肺、壁層胸膜覆蓋胸壁，中間的胸膜腔只有一層液體，使肺貼著胸壁擴張。",c:"16.1"},
 pneumothorax:{t:"氣胸 pneumothorax",d:"空氣進入胸膜腔，胸膜內負壓消失，肺因彈性回縮而塌陷。",c:"16.1"},
 boyle:{t:"波以耳定律 Boyle's law",d:"溫度不變時，氣體的壓力與體積成反比；胸腔變大 → 肺內壓下降 → 空氣流入。",c:"16.2"},
 intrapulm:{t:"肺內壓、胸膜內壓",d:"<b>肺內壓</b>：肺泡內壓力，吸氣約 −3、呼氣約 +3 mmHg（相對大氣）。<b>胸膜內壓</b>：始終低於肺內壓（約 −3 到 −6），兩者差撐開肺。",c:"16.2"},
 compliance:{t:"順應性 compliance",d:"肺容易被撐開的程度；肺纖維化時下降，吸氣費力；肺氣腫時反而上升。",c:"16.2"},
 lungelastic:{t:"肺的彈性 elasticity",d:"肺被撐開後彈回的傾向，來自彈性蛋白纖維與表面張力；平靜呼氣靠它；肺氣腫時被破壞。",c:"16.2"},
 surfacetension:{t:"表面張力 surface tension",d:"肺泡內表面水分子互相吸引使肺泡傾向塌陷；依拉普拉斯定律（P＝2T/r）小肺泡更易塌陷。",c:"16.2"},
 surfactant:{t:"表面活性劑 surfactant",d:"第二型肺泡細胞分泌的磷脂質（主要 DPPC）與蛋白，降低表面張力、防止肺泡塌陷；胎兒約 28–32 週後足量分泌。",c:"16.2"},
 rds:{t:"呼吸窘迫症候群 respiratory distress syndrome",d:"早產兒缺乏表面活性劑，肺泡反覆塌陷、呼吸費力（透明膜疾病）；以人工表面活性劑與呼吸器治療，產前類固醇可預防。成人嚴重肺損傷時為 ARDS。",c:"16.2"},
 diaphragm:{t:"橫膈 diaphragm",d:"胸腔與腹腔之間的圓頂狀骨骼肌，收縮時下降擴大胸腔，是最主要的吸氣肌，由膈神經（C3–C5）支配。",c:"16.3"},
 intercostal:{t:"外肋間肌、內肋間肌",d:"<b>外肋間肌</b>：吸氣時上提肋骨。<b>內肋間肌</b>：用力呼氣時下降肋骨。",c:"16.3"},
 tidal:{t:"潮氣容積 tidal volume",d:"平靜時一次吸入或呼出的氣量，約 500 mL。",c:"16.3"},
 lungvol:{t:"肺容積與肺容量",d:"容積：TV 500、IRV 3,000、ERV 1,200、RV 1,200 mL。容量（相加）：VC＝IRV＋TV＋ERV；TLC＝VC＋RV；FRC＝ERV＋RV；IC＝TV＋IRV。",c:"16.3"},
 vc:{t:"肺活量 vital capacity",d:"盡力吸氣後盡力呼出的最大量＝IRV＋TV＋ERV，約 4,700 mL；限制性肺病時下降。",c:"16.3"},
 rv:{t:"殘氣容積 residual volume",d:"盡力呼氣後仍留在肺內的氣量（約 1,200 mL），肺量計測不到；肺氣腫時增加。",c:"16.3"},
 frc:{t:"功能肋餘容量 functional residual capacity",d:"平靜呼氣後留在肺內的量＝ERV＋RV（約 2,400 mL），使肺泡氣體組成保持穩定。",c:"16.3"},
 deadspace:{t:"死腔 dead space",d:"傳導區中不參與氣體交換的空間，約 150 mL；肺泡換氣量＝（潮氣容積－死腔）× 頻率。",c:"16.3"},
 fev1:{t:"FEV₁、FEV₁/FVC",d:"第一秒用力呼氣量與用力肺活量的比值，正常 ≥ 約 0.8；阻塞性肺病下降。",c:"16.3"},
 restrictive:{t:"限制性、阻塞性肺病",d:"<b>限制性</b>：肺無法充分擴張（纖維化），VC↓、FEV₁/FVC 正常。<b>阻塞性</b>：呼氣氣流受阻（氣喘、肺氣腫、慢性支氣管炎），FEV₁/FVC↓。",c:"16.3"},
 asthma:{t:"氣喘 asthma",d:"呼吸道慢性發炎，支氣管平滑肌對刺激過度反應而收縮（白三烯素、組織胺），通常可逆；以 β₂ 致效劑與吸入型類固醇治療。",c:"16.3"},
 emphysema:{t:"肺氣腫 emphysema",d:"肺泡壁被破壞、融合成大氣囊，交換面積減少、彈性喪失、呼氣時細支氣管塌陷；主因抽菸，屬阻塞性。",c:"16.3"},
 copd:{t:"慢性阻塞性肺病 COPD",d:"慢性支氣管炎與肺氣腫的合稱，呼氣氣流受阻、不完全可逆；病人常體重減輕、肌肉流失。",c:"16.3"},
 fibrosis:{t:"肺纖維化 pulmonary fibrosis",d:"肺組織被結締組織取代，順應性下降，屬限制性肺病；可由石綿、矽塵或不明原因造成。",c:"16.3"},
 partialp:{t:"分壓 partial pressure",d:"混合氣體中某一氣體貢獻的壓力＝總壓 × 該氣體比例（道耳吞定律）；氣體由高分壓擴散到低分壓。",c:"16.4"},
 dalton:{t:"道耳吞定律、亨利定律",d:"<b>道耳吞</b>：總壓＝各分壓之和。<b>亨利</b>：溶解在液體中的氣體量與分壓及溶解度成正比（CO₂ 溶解度約 O₂ 的 20 倍）。",c:"16.4"},
 abg:{t:"動脈血氣 arterial blood gas",d:"測量動脈血的 PO₂（約 100）、PCO₂（約 40）、pH（約 7.40）、HCO₃⁻（約 24）；評估換氣與酸鹼。",c:"16.4、16.8"},
 vq:{t:"通氣—灌流配合 V/Q",d:"肺泡換氣量與血流量的比值（約 0.8）；缺氧時肺小動脈收縮，把血導向通氣好的區域（與體循環相反）。",c:"16.4"},
 respcenter:{t:"呼吸中樞 respiratory centers",d:"延腦（背側呼吸群主吸氣、腹側呼吸群含節律產生者）自動產生節律；橋腦（呼吸調節中樞、長吸中樞）修飾。",c:"16.5"},
 centralchemo:{t:"中樞化學感受器 central chemoreceptors",d:"位於延腦腹側；血中 CO₂ 穿過血腦障壁在腦脊髓液生成 H⁺ 而刺激它；平常調控呼吸最主要的機制。",c:"16.5"},
 periphchemo:{t:"周邊化學感受器 peripheral chemoreceptors",d:"<b>頸動脈體</b>（頸總動脈分叉，舌咽神經）與<b>主動脈體</b>（主動脈弓，迷走神經）；感測 PO₂↓（&lt; 約 60）、PCO₂↑、H⁺↑。國考考過位置。",m:"「體」偵測化學、「竇」偵測壓力。",c:"16.5"},
 carotidbody:{t:"頸動脈體、主動脈體",d:"<b>頸動脈體</b>：頸總動脈分叉處的小團化學感受細胞（舌咽神經），最重要的周邊化學感受器。<b>主動脈體</b>：主動脈弓附近（迷走神經）。",c:"16.5"},
 heringbreuer:{t:"赫鮑二氏反射 Hering-Breuer reflex",d:"肺過度膨脹時，呼吸道伸張受器經迷走神經抑制吸氣，防止過度膨脹。",c:"16.5"},
 hyperventilation:{t:"過度換氣、換氣不足",d:"<b>過度換氣</b>：換氣超過代謝需要，PCO₂↓ → 呼吸性鹼中毒。<b>換氣不足</b>：PCO₂↑ → 呼吸性酸中毒。",c:"16.5、16.8"},
 oxyhb:{t:"氧合、去氧血紅素",d:"<b>氧合血紅素</b>：結合 O₂，鮮紅。<b>去氧血紅素</b>：放出 O₂，暗紅，較能緩衝 H⁺ 與攜帶 CO₂。",c:"16.6"},
 methb:{t:"變性血紅素 methemoglobin",d:"血基質鐵被氧化成 Fe³⁺，無法結合 O₂；可由某些藥物或過多亞硝酸鹽引起。",c:"16.6"},
 carboxyhb:{t:"碳氧血紅素、一氧化碳中毒",d:"CO 與血紅素的親和力約為 O₂ 的 210 倍，佔據結合位並使剩餘 O₂ 不易釋放；呈鮮紅色，脈搏血氧計可能誤判。治療給高濃度或高壓氧。",c:"16.6"},
 odc:{t:"氧合血紅素解離曲線 oxyhemoglobin dissociation curve",d:"S 形：肺（PO₂ 100）飽和約 97%；靜止組織（40）約 75%；上方平坦提供安全餘裕，下方陡峭利於釋氧。",c:"16.6"},
 bohr:{t:"波爾效應 Bohr effect",d:"H⁺ 增加（pH 下降）與 CO₂ 增加使血紅素對 O₂ 親和力下降、曲線右移，在活動組織釋放更多 O₂。",c:"16.6"},
 bpg:{t:"2,3-BPG（2,3-DPG）",d:"紅血球糖解產生的中間產物，結合去氧血紅素的 β 鏈，降低 O₂ 親和力（右移）；貧血、高海拔時增加，庫存血減少。",c:"16.6"},
 hbf:{t:"胎兒血紅素 HbF",d:"2α＋2γ 鏈，與 2,3-BPG 結合較弱，對 O₂ 親和力較高（左移），能從母體血液取得 O₂；出生後逐漸被 HbA 取代。",c:"16.6；第 20 章"},
 sickle:{t:"鐮刀型貧血 sickle-cell anemia",d:"β 鏈第 6 個胺基酸麩胺酸 → 纈胺酸（HbS），去氧時聚合使紅血球呈鐮刀狀，阻塞微血管並易溶血。",c:"16.6"},
 thalassemia:{t:"地中海型貧血 thalassemia",d:"α 或 β 鏈合成不足造成的小球性貧血；台灣帶因率約 6%，建議婚前或產前篩檢，帶因者不應盲目補鐵。",c:"16.6"},
 carbaminohb:{t:"胺甲醯血紅素 carbaminohemoglobin",d:"CO₂ 與血紅素蛋白質部分的胺基結合的形式，約占 CO₂ 運送的 20%。",c:"16.7"},
 chlorideshift:{t:"氯轉移 chloride shift",d:"組織中紅血球內產生的 HCO₃⁻ 移到血漿，Cl⁻ 移入補位；在肺中反向（逆氯轉移）。",c:"16.7"},
 haldane:{t:"何登效應 Haldane effect",d:"去氧血紅素比氧合血紅素更能攜帶 CO₂ 與 H⁺；組織放出 O₂ 有助於帶走 CO₂，在肺則相反。",c:"16.7"},
 acidbase:{t:"酸鹼平衡 acid-base balance",d:"血液 pH 維持 7.35–7.45；靠緩衝系統、肺（調 CO₂）與腎（調 HCO₃⁻）；HCO₃⁻：CO₂ 約 20：1。",c:"16.8；第 17 章"},
 volatileacid:{t:"揮發性酸、非揮發性酸",d:"<b>揮發性</b>：碳酸，可變成 CO₂ 由肺排出。<b>非揮發性</b>（固定酸）：乳酸、酮體、硫酸、磷酸，由腎排出。",c:"16.8"},
 hh:{t:"韓德森—哈索巴赫方程",d:"pH＝6.1＋log（[HCO₃⁻]／0.03 × PCO₂）；HCO₃⁻ 24、PCO₂ 40 時 pH 為 7.4。",c:"16.8"},
 respacid:{t:"呼吸性酸中毒、鹼中毒",d:"<b>呼吸性酸中毒</b>：換氣不足 → PCO₂↑（COPD、呼吸抑制）。<b>呼吸性鹼中毒</b>：過度換氣 → PCO₂↓（焦慮、高海拔）。腎臟代償。",c:"16.8"},
 metacid:{t:"代謝性酸中毒、鹼中毒",d:"<b>代謝性酸中毒</b>：HCO₃⁻↓（酮酸、乳酸、腹瀉、腎衰竭），過度換氣代償。<b>代謝性鹼中毒</b>：HCO₃⁻↑（嘔吐、制酸劑），換氣減少代償。",c:"16.8"},
 dka:{t:"糖尿病酮酸中毒 diabetic ketoacidosis",d:"胰島素嚴重不足時脂肪大量分解產生酮體，造成代謝性酸中毒、高血糖、脫水；呼吸深快（庫斯毛耳呼吸）、口氣有丙酮味。",c:"16.8；第 19 章"},
 kussmaul:{t:"庫斯毛耳呼吸 Kussmaul breathing",d:"代謝性酸中毒時深而快的呼吸，呼出 CO₂ 以代償。",c:"16.8"},
 hyperpnea:{t:"運動換氣增加 exercise hyperpnea",d:"運動時換氣隨代謝等比例增加，動脈血氣幾乎不變；推測來自大腦前饋與肌肉關節的回饋。",c:"16.9"},
 acclimat:{t:"高海拔適應 acclimatization",d:"PO₂↓ → 換氣↑（呼吸性鹼中毒）→ 腎排 HCO₃⁻；2,3-BPG↑；EPO → 紅血球↑（需鐵）；數天至數週完成。",c:"16.9"},
 ams:{t:"高山症 acute mountain sickness",d:"快速上升到高海拔出現的頭痛、失眠、噁心；嚴重時高海拔肺水腫或腦水腫，最重要處置是下降高度；乙醯唑胺可預防。",c:"16.9"}
});
Object.assign(GL_ALIAS,{
 "換氣":"ventilation","肺泡":"alveoli","第一型肺泡細胞":"alvcell","第二型肺泡細胞":"alvcell","傳導區":"condzone","呼吸區":"condzone","黏液纖毛電扶梯":"mucocil",
 "胸膜":"pleura","胸膜腔":"pleura","氣胸":"pneumothorax","波以耳定律":"boyle","肺內壓":"intrapulm","胸膜內壓":"intrapulm","順應性":"compliance",
 "表面張力":"surfacetension","拉普拉斯定律":"surfacetension","表面活性劑":"surfactant","呼吸窘迫症候群":"rds","橫膈":"diaphragm","膈神經":"diaphragm",
 "外肋間肌":"intercostal","內肋間肌":"intercostal","潮氣容積":"tidal","肺活量":"vc","殘氣容積":"rv","功能肋餘容量":"frc","吸氣儲備容積":"lungvol","呼氣儲備容積":"lungvol","總肺容量":"lungvol",
 "死腔":"deadspace","解剖死腔":"deadspace","FEV₁":"fev1","氣喘":"asthma","肺氣腫":"emphysema","COPD":"copd","慢性阻塞性肺病":"copd","肺纖維化":"fibrosis",
 "分壓":"partialp","道耳吞定律":"dalton","亨利定律":"dalton","血氣":"abg","動脈血氣":"abg","通氣—灌流":"vq","呼吸中樞":"respcenter","延腦呼吸中樞":"respcenter",
 "中樞化學感受器":"centralchemo","周邊化學感受器":"periphchemo","頸動脈體":"carotidbody","主動脈體":"carotidbody","赫鮑二氏反射":"heringbreuer",
 "過度換氣":"hyperventilation","換氣不足":"hyperventilation","氧合血紅素":"oxyhb","去氧血紅素":"oxyhb","變性血紅素":"methb","碳氧血紅素":"carboxyhb","一氧化碳":"carboxyhb",
 "解離曲線":"odc","氧合血紅素解離曲線":"odc","波爾效應":"bohr","2,3-BPG":"bpg","胎兒血紅素":"hbf","鐮刀型貧血":"sickle","地中海型貧血":"thalassemia",
 "胺甲醯血紅素":"carbaminohb","氯轉移":"chlorideshift","何登效應":"haldane","酸鹼平衡":"acidbase","揮發性酸":"volatileacid","非揮發性酸":"volatileacid",
 "韓德森—哈索巴赫":"hh","呼吸性酸中毒":"respacid","呼吸性鹼中毒":"respacid","代謝性酸中毒":"metacid","代謝性鹼中毒":"metacid","糖尿病酮酸中毒":"dka","酮酸中毒":"dka",
 "庫斯毛耳呼吸":"kussmaul","運動換氣增加":"hyperpnea","高海拔適應":"acclimat","高山症":"ams"
});

/* ---- end ch16 ---- */
/* ---- ch17 ---- */
Object.assign(GL,{
 nephron:{t:"腎元 nephron",d:"腎臟的功能單位，每腎約 100 萬個：腎小體（腎絲球＋鮑氏囊）→ 近曲小管 → 亨利氏環 → 遠曲小管，再接集尿管。",c:"17.1"},
 renalcorp:{t:"腎小體 renal corpuscle",d:"腎絲球（一團微血管）與包住它的鮑氏囊；血漿在這裡被過濾成濾液。",c:"17.1"},
 glomerulus:{t:"腎絲球、鮑氏囊",d:"<b>腎絲球</b>：入球與出球小動脈之間的一團高壓微血管。<b>鮑氏囊</b>（腎絲球囊）：杯狀包住腎絲球、收集濾液。",c:"17.1、17.2"},
 pct:{t:"近曲小管 proximal convoluted tubule",d:"緊接腎小體、有刷狀緣的彎曲小管；再吸收約 65% 的 Na⁺ 與水、全部葡萄糖與胺基酸、大部分 HCO₃⁻；濾液仍等張。",c:"17.1、17.3"},
 henle:{t:"亨利氏環 loop of Henle",d:"深入髓質的 U 形管：下行枝對水通透、上行枝主動打出 NaCl 而水不通透，形成逆流倍增。",c:"17.1、17.3"},
 dct:{t:"遠曲小管 distal convoluted tubule",d:"回到皮質的小管段，起始處有緻密斑；噻嗪類利尿劑作用處，後段受醛固酮影響。",c:"17.1"},
 cd:{t:"集尿管 collecting duct",d:"多個腎元共用、穿過髓質的管道；受 ADH（水通道蛋白-2）與醛固酮（Na⁺/K⁺）精細調節，決定尿的濃度與成分。",c:"17.1、17.3、17.5"},
 juxtamed:{t:"皮質腎元、近髓質腎元",d:"<b>皮質腎元</b>（約 85%）：亨利氏環短。<b>近髓質腎元</b>（約 15%）：亨利氏環長、深入內髓質，負責濃縮尿液。",c:"17.1"},
 afferent:{t:"入球小動脈、出球小動脈",d:"<b>入球</b>：把血送進腎絲球，交感與自動調節控制其口徑（決定 GFR）。<b>出球</b>：把血帶出腎絲球（不是靜脈），再形成管周微血管。",c:"17.1、17.2"},
 peritubular:{t:"管周微血管、直血管",d:"出球小動脈之後的第二套微血管：<b>管周微血管</b>圍繞腎小管，接收再吸收的物質；<b>直血管</b>沿亨利氏環深入髓質，以逆流交換維持梯度。",c:"17.1、17.3"},
 micturition:{t:"排尿反射 micturition reflex",d:"膀胱充盈 → 伸張受器 → 薦髓中樞 → 副交感使逼尿肌收縮、內括約肌放鬆；大腦與橋腦控制是否允許，並隨意控制外括約肌（陰部神經）。",c:"17.1（國考）"},
 detrusor:{t:"逼尿肌、尿道括約肌",d:"<b>逼尿肌</b>：膀胱壁平滑肌，副交感使其收縮。<b>內括約肌</b>：平滑肌，不隨意。<b>外括約肌</b>：骨骼肌，隨意控制。",c:"17.1"},
 podocyte:{t:"足細胞 podocytes",d:"鮑氏囊內層的細胞，伸出足突包住腎絲球微血管，足突間的過濾縫隙是過濾膜的最後一層。",c:"17.2"},
 filtmembrane:{t:"腎絲球過濾膜",d:"三層：有窗孔的內皮（擋血球）、帶負電的基底膜（擋蛋白）、足細胞過濾縫隙；水與小分子可通過，白蛋白不能。",c:"17.2"},
 gfr:{t:"腎絲球過濾率 GFR",d:"每分鐘兩腎濾出的液體量，約 125 mL/分（180 L/天）；評估腎功能最重要的指標，臨床以 eGFR 估算。",c:"17.2、17.4"},
 netfilt:{t:"淨過濾壓 net filtration pressure",d:"腎絲球微血管靜水壓（約 60）－鮑氏囊靜水壓（約 15）－血漿膠體滲透壓（約 30）≈ 10–15 mmHg。",c:"17.2"},
 tgf:{t:"腎小管腎絲球回饋 tubuloglomerular feedback",d:"緻密斑偵測流過遠端小管的 NaCl；GFR 太高時使入球小動脈收縮，把 GFR 降回來；自動調節機制之一。",c:"17.2"},
 maculadensa:{t:"緻密斑、近腎絲球器",d:"<b>緻密斑</b>：遠曲小管起始處偵測 NaCl 的細胞。與入球小動脈的近腎絲球細胞（分泌腎素）合稱<b>近腎絲球器</b>。",c:"17.2、17.5"},
 proteinuria:{t:"蛋白尿 proteinuria",d:"尿中出現蛋白質（特別是白蛋白），表示腎絲球過濾膜受損；尿白蛋白／肌酸酐比值（UACR）是糖尿病腎病變的早期指標。",c:"17.2、17.6"},
 countercurrent:{t:"逆流倍增系統 countercurrent multiplier",d:"亨利氏環下行枝（水出）與上行枝（NaCl 主動出、水不出）液體流向相反，層層疊加，使髓質滲透壓從 300 增加到約 1,200 mOsm。",c:"17.3"},
 ccexchange:{t:"逆流交換 countercurrent exchange",d:"直血管下行時吸鹽失水、上行時放鹽吸水，使血流不會沖走髓質的濃度梯度。",c:"17.3"},
 nkcc2:{t:"Na⁺–K⁺–2Cl⁻ 共同運輸器 NKCC2",d:"亨利氏環粗上行枝管腔側的運輸蛋白，把 NaCl 移出小管液；環利尿劑抑制它。",c:"17.3、17.6"},
 aqp2:{t:"水通道蛋白-2 aquaporin-2",d:"集尿管主細胞中受 ADH 控制的水通道：ADH → V2 受體 → cAMP → 插入管腔側膜，讓水被髓質吸出。",c:"17.3"},
 obligatory:{t:"必然性、兼性再吸收",d:"<b>必然性</b>（約 85%）：近曲小管與下行枝，不受控制。<b>兼性</b>（約 15%）：集尿管，由 ADH 決定，決定尿量差異。",c:"17.3"},
 clearance:{t:"清除率 renal plasma clearance",d:"每分鐘被腎臟完全清除某物質的血漿量＝尿中濃度 × 尿流量 ÷ 血漿濃度；&lt; GFR 表示再吸收，&gt; GFR 表示分泌。",c:"17.4"},
 inulin:{t:"菊糖 inulin",d:"植物來源的果糖聚合物，只被過濾、不被再吸收或分泌，其清除率＝GFR，是測量 GFR 的標準方法（注意不是胰島素 insulin）。",c:"17.4"},
 creatinine:{t:"肌酸酐 creatinine",d:"肌肉中肌酸與磷酸肌酸分解的產物，產量穩定、主要靠過濾排出；血清肌酸酐（正常約 0.6–1.2 mg/dL）用來估算 eGFR；肌肉量少者偏低。",c:"17.4"},
 egfr:{t:"估計腎絲球過濾率 eGFR",d:"以血清肌酸酐、年齡、性別代入公式估算的 GFR；慢性腎臟病依它分 1–5 期。",c:"17.4、17.6"},
 bun:{t:"血中尿素氮 BUN",d:"血中尿素的氮含量（約 7–20 mg/dL）；腎功能差時上升，但也受高蛋白飲食、脫水、腸胃出血影響，較不專一。",c:"17.4（國考）"},
 pah:{t:"對胺基馬尿酸 PAH",d:"經過腎臟一次幾乎被過濾與分泌完全清除的物質，其清除率≈腎血漿流量（約 625 mL/分）。",c:"17.4"},
 tm:{t:"最大運輸量 Tm、腎閾值",d:"載體數量有限，再吸收有上限（Tm）；葡萄糖的腎閾值約 180 mg/dL，血糖超過時出現糖尿。",c:"17.4"},
 glycosuria:{t:"糖尿 glycosuria",d:"尿中出現葡萄糖；血糖超過腎閾值（約 180 mg/dL）或服用 SGLT2 抑制劑時發生，並引起滲透性利尿。",c:"17.4（國考）"},
 sglt2i:{t:"SGLT2 抑制劑",d:"阻斷近曲小管葡萄糖再吸收的降血糖藥，讓多餘的葡萄糖從尿排出；需注意脫水與泌尿道感染。",c:"17.4"},
 enac:{t:"上皮鈉通道 ENaC",d:"集尿管主細胞管腔側的 Na⁺ 通道，醛固酮增加其數量；amiloride 阻斷它。",c:"17.5"},
 principal:{t:"主細胞、間插細胞",d:"集尿管的兩種細胞：<b>主細胞</b>受醛固酮（Na⁺ 再吸收、K⁺ 分泌）與 ADH（水通道）調節；<b>間插細胞</b>分泌 H⁺ 或 HCO₃⁻，調節酸鹼。",c:"17.5"},
 hyperkalemia:{t:"高血鉀、低血鉀",d:"血鉀正常約 3.5–5.0 mEq/L。<b>高血鉀</b>（腎衰竭、醛固酮不足、酸中毒、保鉀藥物）與<b>低血鉀</b>（嘔吐腹瀉、利尿劑、醛固酮過多、鹼中毒）都可能致命的心律不整。",c:"17.5"},
 ammonia:{t:"氨與銨 NH₃ / NH₄⁺",d:"腎小管分解麩醯胺酸產生 NH₃，與分泌的 H⁺ 結合成 NH₄⁺ 排出；酸中毒時大量增加，是腎臟排酸的主要方式。",c:"17.5"},
 titratable:{t:"可滴定酸 titratable acid",d:"尿中被磷酸鹽緩衝的 H⁺（HPO₄²⁻＋H⁺ → H₂PO₄⁻）。",c:"17.5"},
 loopdiuretic:{t:"環利尿劑 loop diuretics",d:"如 furosemide，抑制亨利氏環粗上行枝的 NKCC2，效力最強；用於水腫、心衰竭；造成低血鉀、低血鎂。",c:"17.6"},
 thiazide:{t:"噻嗪類利尿劑 thiazides",d:"抑制遠曲小管的 Na⁺–Cl⁻ 共同運輸，常用於高血壓；造成低血鉀、高尿酸，減少尿鈣。",c:"17.6"},
 ksparing:{t:"保鉀利尿劑 potassium-sparing diuretics",d:"螺內酯（醛固酮拮抗劑）或 amiloride（阻斷 ENaC），作用在集尿管；效力弱，可能高血鉀。",c:"17.6"},
 mannitol:{t:"甘露醇 mannitol",d:"能被過濾但不被再吸收的糖醇，提高小管液滲透壓而留住水分（滲透性利尿劑），用於降低腦壓。",c:"17.6"},
 aki:{t:"急性腎損傷 acute kidney injury",d:"數小時到數天內腎功能快速下降，原因有腎血流不足、腎毒性藥物（NSAIDs、顯影劑）、尿路阻塞；常可恢復。",c:"17.6"},
 ckd:{t:"慢性腎臟病 chronic kidney disease",d:"腎功能持續下降超過 3 個月，依 eGFR 分 1–5 期；主因糖尿病、高血壓；併發高血鉀、酸中毒、高磷、貧血、高血壓；飲食調整蛋白質、鈉、鉀、磷、水。",c:"17.6"},
 nephrotic:{t:"腎病症候群 nephrotic syndrome",d:"過濾膜受損：大量蛋白尿（&gt; 3.5 g/天）、低白蛋白血症、水腫、高血脂。",c:"17.6"},
 uremia:{t:"尿毒症 uremia",d:"末期腎病時含氮廢物等累積造成的全身症狀：噁心、食慾差、搔癢、疲倦、意識改變。",c:"17.6"},
 dialysis:{t:"透析 dialysis",d:"<b>血液透析</b>：血液流過人工膜清除廢物與多餘水分（每週約 3 次）。<b>腹膜透析</b>：以腹膜為過濾膜。透析病人需增加蛋白質攝取並限制水、鉀、磷。",c:"17.6"},
 renalstone:{t:"腎結石 renal stones",d:"最常見為草酸鈣結石；預防：多喝水、減鈉、適量動物蛋白，不需刻意限鈣；尿酸結石與高普林、尿液偏酸有關。",c:"17.6"}
});
Object.assign(GL_ALIAS,{
 "腎元":"nephron","腎小體":"renalcorp","腎絲球":"glomerulus","鮑氏囊":"glomerulus","近曲小管":"pct","亨利氏環":"henle","遠曲小管":"dct","集尿管":"cd",
 "近髓質腎元":"juxtamed","皮質腎元":"juxtamed","入球小動脈":"afferent","出球小動脈":"afferent","管周微血管":"peritubular","直血管":"peritubular",
 "排尿反射":"micturition","排尿":"micturition","逼尿肌":"detrusor","外括約肌":"detrusor","內括約肌":"detrusor","足細胞":"podocyte","過濾膜":"filtmembrane",
 "腎絲球過濾率":"gfr","GFR":"gfr","淨過濾壓":"netfilt","腎小管腎絲球回饋":"tgf","緻密斑":"maculadensa","近腎絲球器":"maculadensa","蛋白尿":"proteinuria","UACR":"proteinuria",
 "逆流倍增":"countercurrent","逆流交換":"ccexchange","NKCC2":"nkcc2","水通道蛋白-2":"aqp2","必然性再吸收":"obligatory","兼性":"obligatory",
 "清除率":"clearance","菊糖":"inulin","肌酸酐":"creatinine","血清肌酸酐":"creatinine","eGFR":"egfr","BUN":"bun","血中尿素氮":"bun","PAH":"pah",
 "Tm":"tm","腎閾值":"tm","最大運輸量":"tm","糖尿":"glycosuria","SGLT2 抑制劑":"sglt2i","ENaC":"enac","上皮鈉通道":"enac","主細胞":"principal","間插細胞":"principal",
 "高血鉀":"hyperkalemia","低血鉀":"hyperkalemia","NH₄⁺":"ammonia","可滴定酸":"titratable","環利尿劑":"loopdiuretic","噻嗪類":"thiazide","保鉀利尿劑":"ksparing","螺內酯":"ksparing",
 "甘露醇":"mannitol","急性腎損傷":"aki","慢性腎臟病":"ckd","CKD":"ckd","腎病症候群":"nephrotic","尿毒症":"uremia","透析":"dialysis","血液透析":"dialysis","腹膜透析":"dialysis","腎結石":"renalstone"
});

/* ---- end ch17 ---- */
/* ---- ch18 ---- */
Object.assign(GL,{
 gitract:{t:"消化道、附屬器官",d:"<b>消化道</b>：口腔、咽、食道、胃、小腸、大腸。<b>附屬器官</b>：牙齒、舌、唾液腺、肝、膽囊、胰臟，把分泌物送入消化道。",c:"18.1"},
 gilayers:{t:"消化道管壁四層",d:"由內到外：<b>黏膜</b>（上皮、固有層、黏膜肌層）→ <b>黏膜下層</b>（血管、黏膜下神經叢）→ <b>肌肉層</b>（內環外縱、肌間神經叢）→ <b>漿膜</b>。",c:"18.1"},
 ens:{t:"腸神經系統 enteric nervous system",d:"肌間神經叢（運動）與黏膜下神經叢（分泌）中約一億個神經元，能獨立協調消化道的反射，有「第二個腦」之稱。",c:"18.1"},
 icc:{t:"卡哈爾間質細胞 interstitial cells of Cajal",d:"消化道平滑肌間的節律點細胞，產生慢波（基本電節律）。",c:"18.1"},
 peristalsis:{t:"蠕動 peristalsis",d:"食團後方環肌收縮、前方放鬆的波狀運動，把內容物往前推；食道、胃、小腸、大腸都有。",c:"18.1–18.4"},
 salamylase:{t:"唾液澱粉酶 salivary amylase",d:"唾液中分解澱粉 α-1,4 鍵的酵素，飯嚼久變甜；進入胃後被胃酸失活。",c:"18.2"},
 swallow:{t:"吞嚥 deglutition",d:"舌把食團推向咽是隨意的，之後由延腦吞嚥中樞控制不隨意反射：軟顎封鼻咽、會厭蓋喉、呼吸暫停。",c:"18.2"},
 les:{t:"食道下括約肌 LES",d:"食道與胃交界的平滑肌環，平時收縮防止胃內容物逆流；鬆弛無力 → 胃食道逆流。",c:"18.2"},
 gerd:{t:"胃食道逆流 GERD",d:"LES 關不緊使胃酸逆流造成火燒心；建議少量多餐、睡前 2–3 小時不進食、減重、少高脂與巧克力咖啡酒精、戒菸。",c:"18.2"},
 parietal:{t:"壁細胞 parietal cells",d:"胃腺中分泌鹽酸（以 H⁺/K⁺-ATPase）與內在因子的細胞；受組織胺（H₂）、胃泌素、ACh 刺激。",c:"18.2"},
 chiefcell:{t:"主細胞（胃）chief cells",d:"胃腺下段分泌胃蛋白酶原與胃脂酶的細胞。（腎臟集尿管的「主細胞」principal cell 是不同的細胞。）",c:"18.2"},
 gcell:{t:"G 細胞、ECL 細胞、D 細胞",d:"<b>G 細胞</b>（胃幽門部）：胃泌素。<b>ECL 細胞</b>（類腸嗜鉻細胞）：組織胺。<b>D 細胞</b>：體抑素，抑制胃酸。",c:"18.2"},
 pepsin:{t:"胃蛋白酶原、胃蛋白酶 pepsinogen / pepsin",d:"主細胞分泌無活性的胃蛋白酶原，被胃酸（與胃蛋白酶自身）活化成胃蛋白酶，在 pH 約 2 時切斷蛋白質成多胜肽。",c:"18.2、18.7"},
 protonpump:{t:"質子幫浦 H⁺/K⁺-ATPase",d:"壁細胞管腔側耗 ATP 把 H⁺ 打進胃腔、換 K⁺ 進來的幫浦；質子幫浦抑制劑（PPI，-prazole）抑制它，是最強的抑酸藥。",c:"18.2"},
 h2blocker:{t:"H₂ 受體拮抗劑 H₂ blockers",d:"如 cimetidine、famotidine（-tidine），阻斷壁細胞的組織胺 H₂ 受體而減少胃酸；與治療過敏的 H₁ 抗組織胺不同。國考考過。",c:"18.2"},
 alkalinetide:{t:"鹼潮 alkaline tide",d:"壁細胞分泌 H⁺ 的同時把 HCO₃⁻ 送入血液，使飯後血液與尿液暫時偏鹼。",c:"18.2"},
 chyme:{t:"食糜 chyme",d:"胃把食物與胃液攪拌而成的半流體，少量逐次經幽門進入十二指腸。",c:"18.2"},
 hpylori:{t:"幽門螺旋桿菌 Helicobacter pylori",d:"住在胃黏液層的細菌，以尿素酶產生氨中和胃酸；造成慢性胃炎、消化性潰瘍，並與胃癌有關；以抗生素加 PPI 除菌。",c:"18.2"},
 pepticulcer:{t:"消化性潰瘍 peptic ulcer",d:"胃或十二指腸黏膜被胃酸與胃蛋白酶侵蝕；主因幽門螺旋桿菌與 NSAIDs。",c:"18.2"},
 vomiting:{t:"嘔吐 vomiting",d:"延腦嘔吐中樞協調的反射；原因：腸胃刺激、毒素與藥物（化學受器觸發區）、前庭（暈車）、懷孕、顱內壓上升、心理因素。嚴重時造成代謝性鹼中毒、低血鉀。國考考過。",c:"18.2"},
 ctz:{t:"化學受器觸發區 chemoreceptor trigger zone",d:"延腦第四腦室底血腦障壁較弱的區域，偵測血中毒素與藥物（化療、鴉片）並觸發嘔吐。",c:"18.2"},
 dumping:{t:"傾食症候群 dumping syndrome",d:"胃切除或減重手術後食物太快進入小腸：早期因高滲透壓腹痛腹瀉心悸，晚期因胰島素過度分泌而低血糖；建議少量多餐、避免單糖、湯水與固體分開。",c:"18.2"},
 smallint:{t:"十二指腸、空腸、迴腸",d:"<b>十二指腸</b>：接受食糜、膽汁、胰液，吸收鐵與鈣。<b>空腸</b>：主要吸收。<b>迴腸</b>：吸收 B12–內在因子與膽鹽，末端為迴盲瓣。",c:"18.3"},
 villi:{t:"絨毛 villi",d:"小腸黏膜的指狀突起，內有微血管網與乳糜管；與環狀皺襞、微絨毛共同放大吸收面積約 600 倍。",c:"18.3"},
 brushborder:{t:"刷狀緣、刷狀緣酵素",d:"小腸上皮微絨毛形成的表面；嵌在其膜上的酵素（麥芽糖酶、蔗糖酶、乳糖酶、胜肽酶、腸激酶）完成最後的消化。",c:"18.3"},
 enterokinase:{t:"腸激酶 enterokinase",d:"小腸刷狀緣的酵素，把胰蛋白酶原活化成胰蛋白酶，啟動胰臟蛋白酶的連鎖活化。",c:"18.3、18.5"},
 crypt:{t:"腸隱窩 intestinal crypts",d:"絨毛之間向下凹的腺體，含幹細胞，約 3–5 天更新整個小腸上皮。",c:"18.3"},
 segmentation:{t:"分節運動 segmentation",d:"小腸相鄰環肌段交替收縮放鬆，把食糜來回切割混合，是進食後小腸主要的運動。",c:"18.3"},
 mmc:{t:"遷移性運動複合波 MMC",d:"空腹時約每 90 分鐘從胃到迴腸一次的強力蠕動，清掃殘渣與細菌；與胃動素有關。",c:"18.3"},
 colon:{t:"大腸 large intestine",d:"盲腸（闌尾）→ 升、橫、降、乙狀結腸 → 直腸 → 肛管；無絨毛；吸收水與 Na⁺、容納腸道菌、形成糞便。",c:"18.4"},
 massmove:{t:"集團運動、胃結腸反射",d:"每天數次把大段內容物推向直腸的強力收縮，常在餐後由胃結腸反射引發。",c:"18.4"},
 microbiota:{t:"腸道菌相 gut microbiota",d:"大腸中約 10¹³–10¹⁴ 個細菌：發酵纖維產生短鏈脂肪酸、合成維生素 K、與病原菌競爭、訓練免疫。",c:"18.4"},
 scfa:{t:"短鏈脂肪酸 short-chain fatty acids",d:"腸道菌發酵膳食纖維產生的乙酸、丙酸、丁酸；丁酸是結腸上皮主要燃料並抗發炎。",c:"18.4"},
 probiotic:{t:"益生菌、益生質",d:"<b>益生菌</b>：有益的活菌（乳酸桿菌、雙歧桿菌）。<b>益生質</b>：不被消化、促進益菌生長的成分（菊糖、寡醣、抗性澱粉）。",c:"18.4"},
 defecation:{t:"排便反射 defecation reflex",d:"直腸被撐開 → 薦髓 → 副交感使直腸收縮、肛門內括約肌放鬆；外括約肌（骨骼肌）由意志控制。",c:"18.4"},
 diarrhea:{t:"腹瀉 diarrhea",d:"分泌性（霍亂毒素）、滲透性（乳糖不耐、糖醇、鎂鹽）、發炎性、運動性；造成脫水、低血鉀、代謝性酸中毒。國考考過。",c:"18.4"},
 cftr:{t:"CFTR 氯離子通道",d:"上皮細胞的 Cl⁻ 通道：霍亂毒素經 cAMP 使其持續打開而大量分泌水；基因缺陷造成囊腫纖維化。",c:"18.4、18.5"},
 ibd:{t:"發炎性腸病、腸躁症",d:"<b>發炎性腸病</b>（潰瘍性結腸炎、克隆氏症）：慢性免疫性發炎，血便、吸收不良。<b>腸躁症</b>：功能性腸道障礙，腹痛合併腹瀉或便秘，無結構病變。",c:"18.4"},
 portal:{t:"肝門靜脈系統 hepatic portal system",d:"胃、腸、胰、脾的靜脈血匯成肝門靜脈先送到肝臟，再經肝靜脈回心臟；水溶性營養素、酒精、藥物先經肝臟處理。國考考過「首站器官」。",c:"18.5"},
 firstpass:{t:"首渡效應 first-pass effect",d:"口服藥被吸收後先經肝臟代謝，進入全身循環的量減少；舌下、注射可避開。",c:"18.5"},
 lobule:{t:"肝小葉、肝竇",d:"肝臟的結構單位：血液從角落的門脈三合體經<b>肝竇</b>（不連續型微血管，有庫佛氏細胞）流向中央靜脈；膽汁反向流向膽管。",c:"18.5"},
 kupffer:{t:"庫佛氏細胞 Kupffer cells",d:"肝竇中的巨噬細胞，吞噬來自腸道的細菌與老舊紅血球。",c:"18.5"},
 liverfx:{t:"肝臟的功能",d:"解毒（P450、結合、尿素循環）、醣類（肝醣、糖質新生）、脂質（膽固醇、VLDL、酮體）、蛋白質（白蛋白、凝血因子）、儲存（肝醣、A、D、B12、鐵）、製造膽汁。",c:"18.5"},
 bile:{t:"膽汁 bile",d:"肝細胞製造、膽囊儲存濃縮；含膽鹽、磷脂質、膽固醇、膽紅素、HCO₃⁻，不含消化酵素。",c:"18.5"},
 bilesalt:{t:"膽鹽 bile salts",d:"肝臟以膽固醇製成的膽酸與甘胺酸或牛磺酸結合而成，兩親性，乳化脂肪並形成微膠粒；約 95% 經腸肝循環回收。",c:"18.5、18.7"},
 ehc:{t:"腸肝循環 enterohepatic circulation",d:"膽鹽在迴腸被回收，經肝門靜脈回肝臟再分泌；水溶性纖維與膽酸螯合劑減少回收、降低膽固醇。",c:"18.5"},
 urobilinogen:{t:"尿膽素原、糞膽素",d:"腸道細菌把膽紅素轉成尿膽素原：大部分成為糞膽素使糞便呈褐色，少部分再吸收由尿排出。",c:"18.5"},
 gallbladder:{t:"膽囊 gallbladder",d:"儲存並濃縮膽汁（5–20 倍）；脂肪進入十二指腸時 CCK 使其收縮。",c:"18.5"},
 gallstone:{t:"膽結石 gallstones",d:"多為膽固醇結石；危險因子：女性、肥胖、快速減重、懷孕、年齡；阻塞時腹痛、黃疸、可引起胰臟炎。",c:"18.5"},
 pancjuice:{t:"胰液 pancreatic juice",d:"每天約 1.5 L、pH 約 8：HCO₃⁻（胰泌素刺激）＋酵素（CCK 刺激）：澱粉酶、脂酶、蛋白酶原、核酸酶。",c:"18.5"},
 panclipase:{t:"胰脂酶、輔脂酶",d:"<b>胰脂酶</b>把三酸甘油酯切成 2 個脂肪酸與 2-單酸甘油酯；<b>輔脂酶</b>幫它附著在膽鹽包覆的脂肪滴上。orlistat 抑制胰脂酶。",c:"18.5、18.7"},
 panamylase:{t:"胰澱粉酶 pancreatic amylase",d:"胰液中把澱粉分解成麥芽糖、麥芽三糖與 α-極限糊精的主要酵素。",c:"18.5、18.7"},
 trypsin:{t:"胰蛋白酶原、胰蛋白酶",d:"胰臟以無活性的胰蛋白酶原分泌，被腸激酶活化成胰蛋白酶，再活化胰凝乳蛋白酶原、彈性蛋白酶原、羧基胜肽酶原。",c:"18.5、18.7"},
 pancreatitis:{t:"急性胰臟炎 acute pancreatitis",d:"胰酵素在胰臟內提早活化而消化胰臟本身；主因膽結石與酒精；劇烈上腹痛、血中澱粉酶與脂酶升高。",c:"18.5"},
 steatorrhea:{t:"脂肪瀉 steatorrhea",d:"脂肪吸收不良使糞便油亮、浮在水面、惡臭；原因有胰外分泌不足、膽汁不足、迴腸疾病；常伴脂溶性維生素缺乏。",c:"18.5、18.7"},
 gastricphase:{t:"腦期、胃期、腸期",d:"<b>腦期</b>：見聞食物 → 迷走神經 → 胃酸（約 30%）。<b>胃期</b>：擴張與胜肽 → 胃泌素（約 50–60%）。<b>腸期</b>：食糜進十二指腸 → 腸胃反射與腸抑胃素抑制胃。",c:"18.6"},
 gastrin:{t:"胃泌素 gastrin",d:"胃幽門部 G 細胞受胜肽、胺基酸、胃擴張、迷走神經刺激而分泌，促進胃酸分泌與胃黏膜生長。",c:"18.6"},
 secretin:{t:"胰泌素 secretin",d:"十二指腸 S 細胞受酸（pH &lt; 約 4.5）刺激分泌，使胰臟與膽管分泌 HCO₃⁻，並抑制胃酸與胃排空；第一個被發現的激素。",c:"18.6"},
 cck:{t:"膽囊收縮素 CCK",d:"十二指腸與空腸 I 細胞受脂肪酸與胺基酸刺激分泌：使胰臟分泌酵素、膽囊收縮、Oddi 括約肌放鬆，抑制胃排空並產生飽足感。",c:"18.6"},
 somatostatin2:{t:"體抑素（胃腸）somatostatin",d:"胃與腸的 D 細胞受酸刺激分泌，廣泛抑制胃泌素、胃酸與其他消化激素。",c:"18.2、18.6"},
 entero_reflex:{t:"腸胃反射 enterogastric reflex",d:"酸、脂肪、高滲透壓食糜進入十二指腸時，經神經抑制胃的蠕動與分泌，減慢胃排空。",c:"18.6"},
 lactose:{t:"乳糖酶、乳糖不耐",d:"刷狀緣乳糖酶把乳糖分解成葡萄糖與半乳糖；多數亞洲成人斷奶後活性下降，乳糖到大腸被發酵 → 脹氣與滲透性腹瀉。優酪乳、熟成起司較易耐受。",c:"18.3、18.7"},
 glut5:{t:"GLUT5、GLUT2",d:"<b>GLUT5</b>：腸細胞管腔側的果糖運輸蛋白。<b>GLUT2</b>：基底側，讓葡萄糖、半乳糖、果糖進入血液；肝臟與 β 細胞也有。",c:"18.7"},
 emulsify:{t:"乳化 emulsification",d:"膽鹽與卵磷脂把大脂肪球分散成小滴，增加脂酶作用的表面積，不改變化學結構。",c:"18.7"},
 lpl:{t:"脂蛋白脂酶 lipoprotein lipase",d:"位於脂肪與肌肉微血管內皮，分解乳糜微粒與 VLDL 中的三酸甘油酯，讓脂肪酸進入組織。",c:"18.7；第 19 章"},
 mct2:{t:"中鏈三酸甘油酯 MCT",d:"8–12 碳脂肪酸組成，不需膽鹽與乳糜微粒，直接經肝門靜脈吸收；用於脂肪吸收不良、膽汁或胰液不足、淋巴異常。",c:"18.7"},
 peptidase:{t:"內切、外切胜肽酶",d:"<b>內切</b>：從鏈中間切（胃蛋白酶、胰蛋白酶、胰凝乳蛋白酶、彈性蛋白酶）。<b>外切</b>：從末端切（羧基胜肽酶、胺基胜肽酶）。",c:"18.7"},
 pept1:{t:"PepT1",d:"小腸上皮吸收二胜肽與三胜肽的運輸蛋白（與 H⁺ 共同運輸），速度比游離胺基酸快；胜肽配方的吸收基礎。",c:"18.7"},
 ironabs:{t:"鐵的吸收",d:"主要在十二指腸：非血基質 Fe³⁺ 需還原成 Fe²⁺（維生素 C、胃酸幫助）經 DMT1 吸收；血基質鐵吸收率較高；經運鐵素蛋白出細胞，受鐵調素抑制。",c:"18.7；第 13 章"},
 b12abs:{t:"維生素 B12 的吸收",d:"胃酸與胃蛋白酶釋出 → R 蛋白 → 胰蛋白酶分解 R 蛋白 → 與內在因子結合 → 迴腸末端吸收；胃或迴腸切除、萎縮性胃炎、長期 PPI 影響吸收。",c:"18.7"}
});
